static const int kWyrmSpot = 29;
static const int kBreakoutSpot = 30;
static bool IsWyrmName(const std::string& n) { return n == "Tri-Wyrm"; }
// Health for a spot's monster: level*3, except the world boss.
// Monster health (2026-09-30: was 3 per level everywhere - a level 22 orc had 66 and
// a dungeon boss ~120, so a party melted them). Regular monsters now carry 6 per
// level; bosses 20 per level, and 20% more for every follower slot you bring
// (a full five-slot party doubles it), so a warband can't steamroll a lair.
static float MonsterMaxHp(const GameState& s, float level, bool boss) {
    if (!boss) return std::max(1.0f, level * 6.0f);
    return std::max(1.0f, level * 20.0f * (1.0f + 0.2f * (float)std::min(FollowersUsed(s), kFollowerSlots)));
}
static bool WildSpotIsBoss(int idx) {
    const WildernessMonsterSpot& sp = kWildernessMonsterSpots[(size_t)idx];
    return sp.name == "Orc Warlord" || idx == kBreakoutSpot;
}
static float WildSpotMaxHp(const GameState& s, int idx) {
    const WildernessMonsterSpot& sp = kWildernessMonsterSpots[(size_t)idx];
    return sp.iconIdx == kWyrmIcon ? kWyrmMaxHp : MonsterMaxHp(s, (float)sp.level, WildSpotIsBoss(idx));
}
static const int kWildMonsterIconCount = 9; // iconIdx 0-4 classic, 5 Ice Wolf, 6 Frostbitten Husk, 7 Rock Golem, 8 Mountain Cat
static_assert(kWildernessMonsterSpots.size() == kWildMonsterSpotCount,
              "wildSpotRespawn is sized by kWildMonsterSpotCount - keep them in sync");
// --- UO player-killer Rival (2026-09-24): epithet ladder, tuning, and helpers ---
// Display name escalates with rivalKillsOnPlayer - the red earns its reputation.
static std::string RivalEpithetName(const GameState& s) {
    // (2026-09-28 cleanup) the Rival is Murder Inc.'s own master, Kael Vorn - one band of killers, not two
    if (s.rivalKillsOnPlayer >= 8) return "Kael Vorn, Bane of the Wilderness";
    if (s.rivalKillsOnPlayer >= 5) return "Kael Vorn the Merciless";
    if (s.rivalKillsOnPlayer >= 3) return "Kael Vorn the Relentless";
    if (s.rivalKillsOnPlayer >= 1) return "Kael Vorn the Ruthless";
    return "Kael Vorn, Master of Murder Inc.";
}
// All rival-hunt tuning in one place.
static const float kRivalSprintSpeed = 260.0f;   // faster than kPlayerSpeed (220): it CAN run you down in the open
static const float kRivalSprintDuration = 3.0f;
static const float kRivalRecoverSpeed = 110.0f;  // the breather gait (== the old flat hunt speed)
static const float kRivalRecoverDuration = 4.0f;
static const float kRivalSprintStuckTime = 1.5f;  // grace period before the stuck/juke check runs
static const float kRivalSprintStuckEps = 40.0f;  // sprint breaks if it closes less than this (blocked on something)
static const float kRivalCatchRange = 55.0f;     // auto-engage when a hunt closes to this (inside melee+collision)
static const float kRivalHuntBaseChance = 0.5f;
static const float kRivalHuntVulnerableBonus = 0.25f; // gathering / mid-fight / below half HP: it smells blood
static const float kRivalHuntSafetyPenalty = 0.35f;   // near return gate / dungeon entrances / Town2 gate
static const float kRivalSafetyRadius = 420.0f;
static const float kRivalStalkChance = 0.35f;    // share of hunts that begin as a visible stalk
static const float kRivalStalkMin = 10.0f, kRivalStalkMax = 20.0f;
static const float kRivalStalkRange = 400.0f;    // preferred shadowing distance
static const float kRivalStalkSpeed = 150.0f;
static const float kRivalPursuitTime = 15.0f;    // overworld chase after you break away from its fight
static const float kRivalCorpseLootPct = 0.15f;  // of CARRIED gold (bank gold is never touched)
static const float kRivalBannerTime = 4.0f;
static const float kRivalVelSmooth = 6.0f;       // exponential smoothing rate for the intercept velocity
static const float kRivalTeleportGuard = 300.0f;  // frame-to-frame player jump above this zeroes velocity (gate travel)
static const float kRivalHuntGiveUpTime = 25.0f; // seconds of hunting without catching the player before it gives up

// --- Murder Inc. guild blades (2026-09-24) -------------------------------------
// The champion's crew: weaker, simpler, longer leashes. They reuse the champion's
// hunt/stalk/intercept code paths but never sprint, never loot, never earn
// epithets, and never touch rivalKillsOnPlayer. Pair hunts are the signature:
// 30% of blade hunts become a two-blade jump ("Murder Inc. is hunting you!").
// Coordination: the champion never pair-hunts (solo predator - his identity);
// while the champion is hunting/stalking, blades don't start hunts; blades never
// freelance while another blade is hunting (pairs form ONLY via the pair roll).
// Cap: 2 hunters at once, never all 3 + the champion - that's unplayable.
static const float kBladeHuntBaseChance = 0.25f;  // ~half the champion's appetite
static const float kBladeHuntGiveUpTime = 12.0f;  // shorter leash than the champion's 25s
static const float kBladeHuntSpeed = 130.0f;       // flat - no sprint bursts. Scary in pairs, outrunnable solo
static const float kBladePatrolSpeed = 55.0f;     // same amble as the champion's patrol
static const float kBladeStalkChance = 0.25f;     // share of blade hunts that begin as a visible stalk
static const float kBladeStalkRange = 350.0f;     // blades shadow a little closer than the champion
static const float kBladePairChance = 0.30f;      // share of blade hunt commits that become pair hunts
static const float kBladeLevelFracMin = 0.45f;    // blades track 45-60% of the champion's
static const float kBladeLevelFracMax = 0.60f;    // target power - always beatable, never the main event

// Fixed guild names - no epithet ladder for the crew, just rank numerals.
// Named killers (2026-09-28, #72): each Blade is a person with a name and a price
// on their head. Hang one and a new recruit takes the colours; one who beats you
// walks away richer, with a bigger bounty.
static const char* kBladeNames[] = {
    "Varg \"the Knife\" Ostrel", "Mirela Blackthorn", "Osric \"Nine Fingers\" Vane", "Hessa the Quiet",
    "Dunmore Kell", "Sable Ravenscar", "Tobin \"Rook\" Marrow", "Ilsa Grimwater", "Corvin the Smiling",
    "Brakka Stonejaw", "Lyle \"Whisper\" Fenn", "Garret Holloway", "Nyx Umbermoor", "Rolf the Butcher",
    "Ada \"Red Hands\" Crane", "Jory Ashgrave",
};
static const int kBladeNameCount = (int)(sizeof(kBladeNames) / sizeof(kBladeNames[0]));
static std::string BladeName(int bi) {
    bi = std::clamp(bi, 0, 2);
    int n = g_skillOwner ? g_skillOwner->bladeName[(size_t)bi] : bi;
    return kBladeNames[((n % kBladeNameCount) + kBladeNameCount) % kBladeNameCount];
}
// True while the guild has an active threat - used to keep hunts to one at a time.
static bool GuildThreatActive(const GameState& s, int exceptBlade = -1) {
    if (s.rivalActivity == GameState::RivalActivity::Hunting ||
        s.rivalActivity == GameState::RivalActivity::Stalking) return true;
    for (int j = 0; j < kBladeCount; j++) {
        if (j == exceptBlade) continue;
        if (s.blades[j].activity == GameState::RivalActivity::Hunting ||
            s.blades[j].activity == GameState::RivalActivity::Stalking) return true;
    }
    return false;
}
// Tracking (2026-09-27): Murder Inc.'s hunts and stalks only announce themselves to
// someone who can read the signs. Every warning is a roll on effective Tracking
// (none at 0 - they simply arrive); being hunted teaches it, so even a novice
// slowly learns. At 40+ the warning also says which way the tracks lead.
// Young (UO-style new-player protection): during the first-steps guide and the
// first 20 minutes of play, nobody hunts you.
static bool PlayerYoung(const GameState& s) { return s.starterStep >= 0 || s.youngT > 0.0f; }
static std::string CompassWord(Vector2 from, Vector2 to) {
    float a = atan2f(to.y - from.y, to.x - from.x) * RAD2DEG; // +y is south
    static const char* dirs[8] = { "east", "southeast", "south", "southwest", "west", "northwest", "north", "northeast" };
    int i = ((int)floorf((a + 22.5f + 360.0f) / 45.0f)) % 8;
    return dirs[i];
}
static bool TrackingSenses(GameState& s, Vector2 hunterPos, std::string* dirNote) {
    SkillUseGain(s.tracking, 0.5f, 15.0f); // being hunted is a hard lesson (plus a slow passive gain while roaming)
    float t = EffectiveSkill(s, &GameState::tracking);
    if (t <= 0.0f || RandUnit() > 0.3f + t / 100.0f * 0.7f) return false;
    if (dirNote) *dirNote = t >= 40.0f ? " (tracks from the " + CompassWord(s.wildernessPlayerPos, hunterPos) + ")" : "";
    return true;
}
static void BladeStartHunt(GameState& s, int bi, int partner) {
    auto& b = s.blades[bi];
    b.activity = GameState::RivalActivity::Hunting;
    b.activityTimer = kBladeHuntGiveUpTime;
    if (partner >= 0 && partner < kBladeCount && partner != bi) {
        auto& p = s.blades[partner];
        p.activity = GameState::RivalActivity::Hunting;
        p.activityTimer = kBladeHuntGiveUpTime;
    }
    std::string dir;
    if (!TrackingSenses(s, b.pos, &dir)) return; // no Tracking: no warning - they just come
    s.rivalBanner = partner >= 0 && partner < kBladeCount && partner != bi ? "Murder Inc. is hunting you!" : "The " + BladeName(bi) + " is hunting you!";
    s.rivalBannerTimer = kRivalBannerTime;
    s.logLine = s.rivalBanner + dir;
    PlaySfx(SfxId::Hunt);
}
static void BladeStartStalk(GameState& s, int bi) {
    auto& b = s.blades[bi];
    b.activity = GameState::RivalActivity::Stalking;
    b.stalkTimer = kRivalStalkMin + RandUnit() * (kRivalStalkMax - kRivalStalkMin);
    std::string dir;
    if (!TrackingSenses(s, b.pos, &dir)) return;
    s.rivalBanner = "You feel watched...";
    s.rivalBannerTimer = kRivalBannerTime * 0.75f;
    s.logLine = "You feel watched..." + dir;
    PlaySfx(SfxId::Hunt);
}

static void RivalStartHunt(GameState& s) {
    s.rivalActivity = GameState::RivalActivity::Hunting;
    s.rivalActivityTimer = kRivalHuntGiveUpTime;
    s.rivalSprinting = true; // opens with a sprint - the burst out of the treeline
    s.rivalSprintTimer = kRivalSprintDuration;
    s.rivalSprintStartDist = Dist(s.rivalPos, s.wildernessPlayerPos);
    s.rivalSprintStartVel = s.rivalPlayerVel;
    std::string nm = RivalEpithetName(s);
    std::string dir;
    if (!TrackingSenses(s, s.rivalPos, &dir)) return;
    s.rivalBanner = s.rivalGrudge >= 1.0f ? "The " + nm + " wants revenge!" : "The " + nm + " is hunting you!";
    s.rivalBannerTimer = kRivalBannerTime;
    s.logLine = "The " + nm + " is hunting you!" + dir;
    PlaySfx(SfxId::Hunt);
}
static void RivalStartStalk(GameState& s) {
    s.rivalActivity = GameState::RivalActivity::Stalking;
    s.rivalStalkTimer = kRivalStalkMin + RandUnit() * (kRivalStalkMax - kRivalStalkMin);
    std::string dir;
    if (!TrackingSenses(s, s.rivalPos, &dir)) return;
    s.rivalBanner = "You feel watched...";
    s.rivalBannerTimer = kRivalBannerTime * 0.75f;
    s.logLine = "You feel watched..." + dir;
    PlaySfx(SfxId::Hunt);
}
// UO red loots your corpse: 15% of carried gold on every rival kill (bank gold is
// never touched), plus one random backpack item on the ordinary-loss path - the
// murderer-loss path already strips the whole backpack, so the empty check skips it
// there naturally. Called AFTER the loss function so it appends to that log line.
static void RivalCorpseLoot(GameState& s) {
    s.rivalKillsOnPlayer++;
    int loot = (int)std::round(s.gold * kRivalCorpseLootPct);
    s.gold = std::max(0, s.gold - loot);
    s.rivalMind.gold += loot; // your gold rides off in its purse - take it back
    s.rivalGrudge = std::max(0.0f, s.rivalGrudge - 1.0f); // score settled, for now
    std::string msg = RivalEpithetName(s) + " loots your corpse (" +
                      std::to_string(loot) + " gold)";
    if (!s.backpack.empty()) {
        int idx = std::rand() % (int)s.backpack.size();
        msg += " and takes your " + s.backpack[idx].name;
        s.rivalStash.push_back(s.backpack[idx]); // it's on the rival's body now - kill it to get it back
        s.backpack.erase(s.backpack.begin() + idx);
    }
    msg += ".";
    s.logLine += " " + msg;
}
// "As if it were a WildernessMonsterSpot" stats for whichever monster is currently
// engaged. The Rival no longer has a real kWildernessMonsterSpots row (see
// GameState::rivalLevel's comment) - everything that used to read
// kWildernessMonsterSpots[am.spotIdx] unconditionally now goes through this instead, so
// the Rival's stats come from its own persistent GameState::rivalLevel. Gold/leather
// scale off rivalLevel using roughly the same ratio the static Bandit/Highway entries
// already use (~0.75x/~0.5x of level).
struct EngagedMonsterStats { std::string name; int level; int baseGold; int baseLeather; };
static EngagedMonsterStats EngagedWildMonsterStats(const GameState& s, const GameState::ActiveMonster& am) {
    if (am.isRival) {
        int lvl = std::max(1, (int)std::round(s.rivalLevel));
        return { RivalEpithetName(s), lvl, std::max(1, (int)std::round(lvl * 0.75f)) + s.rivalMind.gold / 2, std::max(1, (int)std::round(lvl * 0.5f)) };
    }
    if (am.bladeIdx >= 0 && am.bladeIdx < kBladeCount) {
        int lvl = std::max(1, (int)std::round(s.blades[am.bladeIdx].level));
        return { BladeName(am.bladeIdx), lvl, std::max(1, (int)std::round(lvl * 0.75f)) + s.blades[am.bladeIdx].mind.gold / 2, std::max(1, (int)std::round(lvl * 0.5f)) };
    }
    const WildernessMonsterSpot& spot = kWildernessMonsterSpots[am.spotIdx];
    return { spot.name, spot.level, spot.baseGold, spot.baseLeather };
}
// Called right before ending a fight against the Rival (win, loss, or a successful
// flee) - nudges its persistent level partway toward the player's current
// CombatPower() (same "roughly as strong as you" idea RollMurdererLevel already uses
// for ambushers, ± the same variance) rather than snapping instantly, so it escalates
// across repeated encounters instead of spiking. Also remembers where the fight ended
// so roaming resumes from there instead of snapping back to some old fixed spot.
static const float kRivalGrowthLerpPerFight = 0.25f;
static void RivalFightEnded(GameState& s, const GameState::ActiveMonster& am) {
    s.rivalPos = am.pos;
    float target = (float)CombatPower(s) * (0.9f + RandUnit() * 0.2f);
    s.rivalLevel = std::clamp(s.rivalLevel + (target - s.rivalLevel) * kRivalGrowthLerpPerFight, 5.0f, 500.0f);
    s.rivalActivity = GameState::RivalActivity::Patrol;
    s.rivalActivityTimer = 0.0f; // pick a fresh patrol target immediately rather than waiting out a stale timer
    // Living guild (2026-09-26): its wounds carry over, and beaten means gone for
    // a while (it limps back to camp later) with half its purse left on the body.
    GameState::GuildMind& m = s.rivalMind;
    m.hpFrac = std::clamp(am.hp / std::max(1.0f, am.maxHp), 0.0f, 1.0f);
    m.task = kGtNone; m.working = false;
    m.huntCooldown = 45.0f + RandUnit() * 45.0f;
    if (am.hp <= 0.0f) {
        m.downT = 150.0f + RandUnit() * 120.0f;
        m.gold -= m.gold / 2;
        m.cornered = false;
        s.rivalGrudge = std::min(5.0f, s.rivalGrudge + 1.0f);
        s.rivalPos = kGuildAbsentPos;
    }
}
// Called when a fight against a blade ends (win, loss, or disengage) - persists
// its position and nudges its level toward 45-60% of the champion's target power,
// never above the champion's own level. The crew stays beneath the boss.
static int BladeBountyGold(const GameState& s, int bi) {
    return 150 + (int)(s.blades[(size_t)std::clamp(bi, 0, 2)].level * 6.0f) + s.bladeBounty[(size_t)std::clamp(bi, 0, 2)];
}
static void BladeFightEnded(GameState& s, int bi, const GameState::ActiveMonster& am) {
    auto& b = s.blades[bi];
    b.pos = am.pos;
    float target = (float)CombatPower(s) *
                   (kBladeLevelFracMin + RandUnit() * (kBladeLevelFracMax - kBladeLevelFracMin));
    target = std::min(target, std::max(5.0f, s.rivalLevel)); // never out-level the champion
    b.level = std::clamp(b.level + (target - b.level) * kRivalGrowthLerpPerFight, 5.0f, 500.0f);
    b.activity = GameState::RivalActivity::Patrol;
    b.activityTimer = 0.0f; // pick a fresh patrol target immediately
    b.autoEngage = false;
    GameState::GuildMind& m = b.mind; // same carry-over as the champion's
    m.hpFrac = std::clamp(am.hp / std::max(1.0f, am.maxHp), 0.0f, 1.0f);
    m.task = kGtNone; m.working = false;
    m.huntCooldown = 45.0f + RandUnit() * 45.0f;
    if (am.hp > 0.0f && s.hp <= 0) { // they beat you and walk free: the price on their head grows (#72)
        s.bladeBounty[(size_t)bi] += 60;
        Journal(s, BladeName(bi) + " walks away from your body. The Town Hall raises the bounty to " +
                   std::to_string(BladeBountyGold(s, bi)) + " gold.");
    }
    if (am.hp <= 0.0f && s.bountyTarget == bi && !s.bountyDone) { // the contract is filled (#72)
        s.bountyDone = true;
        s.bountyPay = BladeBountyGold(s, bi);
        Journal(s, "WANTED no more: " + BladeName(bi) + " is dead. Collect your bounty at the Town Hall.");
        s.rivalBanner = "Bounty filled!"; s.rivalBannerTimer = kRivalBannerTime;
        s.bladeBounty[(size_t)bi] = 0;
        s.bladeName[(size_t)bi] = s.bladeNextName++ % kBladeNameCount; // hanged; a new recruit takes the colours
    }
    if (am.hp <= 0.0f) {
        m.downT = 120.0f + RandUnit() * 90.0f;
        m.gold -= m.gold / 2;
        m.cornered = false;
        s.rivalGrudge = std::min(5.0f, s.rivalGrudge + 0.4f); // the boss hears about it
        b.pos = kGuildAbsentPos;
    }
}
// Tuning for the live engagement above. Melee range (60) sits just past where
// ResolveCircleCollision already naturally separates two kNodeRadius*0.7 (35) circles
// plus kPlayerRadius (17) - i.e. collision alone settles a chasing monster at roughly
// sword's-reach, this just confirms "in range" once it does. Chase speed (90) is well
// under kPlayerSpeed (220) so the player can always outrun/kite one; the leash (250)
// keeps a chasing monster from wandering into a neighboring node's territory, and the
// disengage range (320) lets it "lose interest" if the player breaks away.
static const float kWildMeleeRange = 60.0f;
static const float kWildMonsterChaseSpeed = 140.0f; // 2026-09-27: was 90 - aggressive monsters really come for you (you can still outrun them at 220)
static const float kWildMonsterLeashRange = 250.0f;
static const float kWildDisengageRange = 320.0f;

// The Rival Adventurer's out-of-combat roaming (2026-09-23, "Rival hunts you" plan) -
// see GameState::rivalLevel's comment for why it's a fully separate entity rather than
// a kWildernessMonsterSpots row. Patrol is slower than a chasing monster (it's not
// actually chasing anything); Hunting is faster than kWildMonsterChaseSpeed so it reads
// as a real escalation once it commits to coming after the player.
static const float kRivalPatrolSpeed = 55.0f;
static const float kRivalArrivalRadius = 24.0f; // "close enough" to a patrol waypoint to pause there
static const float kRivalPauseDuration = 4.0f;  // how long it lingers at a waypoint (the "gathering/fighting" beat)
static const float kRivalHuntCheckMin = 30.0f, kRivalHuntCheckMax = 90.0f; // how often it re-rolls whether to start hunting
// (Hunt speed/chance/give-up now live in the UO player-killer tuning block above:
// kRivalSprintSpeed/kRivalRecoverSpeed, kRivalHuntBaseChance, kRivalHuntGiveUpTime.)
// Called once per frame from DrawWildernessScreen, before the nearest-interactable
// search, so s.rivalPos is current for this frame's distance checks - only while it
// isn't already the thing you're fighting (updateTacticalOpponentAI owns movement then).
static const float kWildPlayerAttackCooldown = 0.8f;
static const float kWildMonsterAttackCooldown = 1.3f;
// Per-spell recharge for live spellcasting (2026-09-25, combat feel) - each spell
// runs its own 1.2s clock instead of one global lockout, so different spells chain
// (Spark Dart then Ember Burst both go off) while each spell keeps its old pacing.
// A short global cast lock (one cast animation) sits underneath so casts can't
// machine-gun; mana costs are untouched. Magic's rhythm stays independent of
// swing speed, same reasoning as PlayerSwingCooldown existing at all.
static const float kSpellCooldown = 1.2f;
static const float kCastLockTime = 0.35f;
// How long the hero sprite holds its Attack animation after a swing. Originally a
// DrawRing arc, then (2026-09-22) a procedural rotation of the walk-cycle sprite since
// no dedicated attack-animation art existed for the knight sprite at the time; as of
// 2026-09-23 the hero sheet (assets/hero/hero_v2.png) has real per-direction attack
// frames, so this now just gates ActorAnim::Attack in DrawPlayer instead of driving a
// fake rotation effect.
static const float kSwingEffectDuration = tfmotion::swingDuration;
// Same idea as kSwingEffectDuration but for spellcasting, gating ActorAnim::Cast -
// longer than the swing window since each cast already has its own per-spell
// cooldown (kSpellCooldown) to read against, unlike the DEX-scaled swing timer.
static const float kCastEffectDuration = 0.35f;
// DEX-based swing speed (Mark's own design, not from the JS prototype - see the
// STR/DEX/INT growth entry near MaybeGainStat/kStatCapTotal above; the JS never gave
// DEX any effect on attack timing at all). Anchored so DEX 10 (the starting default)
// matches the old flat kWildPlayerAttackCooldown exactly - nobody's swing gets slower
// than today's baseline - scaling down to 0.4s (2x speed) at DEX 100
// (kStatCapIndividual, the individual stat cap), linear in between.
static float PlayerSwingCooldown(const GameState& s) {
    int dex = EffDex(s);
    if (dex > kStatCapIndividual) // (2026-09-27) past 100 from gear/magic: a little faster, never below 0.35s
        return std::max(0.35f, 0.4f - (dex - kStatCapIndividual) / 50.0f * 0.05f);
    float t = std::clamp((dex - 10) / (float)(kStatCapIndividual - 10), 0.0f, 1.0f);
    return kWildPlayerAttackCooldown - t * (kWildPlayerAttackCooldown - 0.4f);
}

// ---- Threat read (2026-09-27) ----
// "An easy way to identify threats in the wild": every monster gets a UO/EQ-
// style con color from how the fight would go - seconds for you to kill it vs
// seconds for it to kill you, from the same hit/damage formulas the live fight
// uses (your swing + pet; its level-scaled bite against your armor).
enum ThreatTier { kThreatTrivial, kThreatEasy, kThreatFair, kThreatTough, kThreatDeadly };
static int ThreatOf(const GameState& s, int monsterLevel) {
    int power = CombatPower(s);
    float weaponSkillBonus = EffectiveSkill(s, ActiveWeaponSkillField(s)) * 0.2f;
    float hit = PlayerHitChance(s, monsterLevel) / 100.0f;
    float myDps = hit * power / PlayerSwingCooldown(s);
    myDps *= 1.0f + 0.35f * (float)ActivePets(const_cast<GameState&>(s)).size(); // each pet adds roughly a third again
    float itsHit = MonsterHitChance(s) / 100.0f;
    float itsDmg = std::max(1.0f, monsterLevel * 1.1f - TotalDefense(s) * 0.3f);
    float itsDps = itsHit * itsDmg / kWildMonsterAttackCooldown;
    float tKillIt = std::max(1.0f, monsterLevel * 3.0f) / std::max(0.05f, myDps);
    float tKillMe = std::max(1.0f, (float)s.hp) / std::max(0.05f, itsDps);
    float r = tKillIt / tKillMe; // < 1: you win the race
    if (r < 0.15f) return kThreatTrivial;
    if (r < 0.45f) return kThreatEasy;
    if (r < 0.85f) return kThreatFair;
    if (r < 1.40f) return kThreatTough;
    return kThreatDeadly;
}
static Color ThreatColor(int t) {
    switch (t) {
        case kThreatTrivial: return Color{ 170, 170, 170, 255 }; // grey: not worth your time
        case kThreatEasy:    return Color{ 110, 215, 110, 255 }; // green
        case kThreatFair:    return Color{ 240, 215, 90, 255 };  // yellow
        case kThreatTough:   return Color{ 245, 150, 60, 255 };  // orange
        default:             return Color{ 235, 70, 60, 255 };   // red: run
    }
}
static const char* ThreatWord(int t) {
    static const char* w[] = { "Trivial", "Easy", "Fair fight", "Tough", "Deadly" };
    return w[std::clamp(t, 0, 4)];
}
// UO-style aggression: monsters that are a real fight for you notice you from
// here and come for you (trivial ones ignore you). The King's Road's patrols
// halve it, and Young players get a shorter reach while they learn.
static const float kWildNoticeRange = 200.0f;
static float WildNoticeRange(const GameState& s, int monsterLevel) {
    if (ThreatOf(s, monsterLevel) == kThreatTrivial) return 0.0f;
    float r = kWildNoticeRange;
    if (PlayerYoung(s)) r *= 0.6f;
    if (PlayerRoadWarded(s.wildernessPlayerPos)) r *= 0.5f;
    return r;
}

// Purely decorative scatter (no collision) - same role as Town's kFoliagePositions.
// CraftPix "Rocks & Bushes" (assets/wilderness/PNG/), same license as the tame-spot art.
// 3=tree (reuses GameAssets.wildTree, the same texture wood-gather nodes use) and
