// ---- The living guild (2026-09-26) ---------------------------------------------
// Between hunts the champion and his blades live like players do: they chop,
// mine and fish at the real gather nodes, farm the real monster spots (a kill
// takes that spot off the map until it respawns - they compete with you for
// it), rest at the camp when hurt, and walk to a town gate to sell a full pack.
// They carry what they earn: beat one and half its purse is on the body; die to
// the champion and your gold rides off with them. Whether to jump you is a
// judgement, not a dice roll on a timer: they have to be near enough to notice
// you, and they weigh their own health and strength (blades count nearby
// crewmates) against yours - strong and healthy against weak or hurt, they
// strike; hurt or outmatched, they back off; killed by you, they hold a grudge.
static Vector2 WildernessMonsterLivePos(int idx, float worldTime);
static float RollWildRespawn();
static const GameState::ActiveMonster* FindWildExtra(const GameState& s, int spotIdx);
static bool WildBlocked(Vector2 p);
static void WildTerrainResolve(Vector2& pos, Vector2 prev);

static int GuildGatherKind(const std::string& r) { return r == "wood" ? 1 : (r == "fish" ? 3 : 2); }
static GameState::GuildMind& GuildMindOf(GameState& s, int who) { return who < 0 ? s.rivalMind : s.blades[who].mind; }
static Vector2& GuildPosOf(GameState& s, int who) { return who < 0 ? s.rivalPos : s.blades[who].pos; }
static std::string GuildWho(int who) { return who < 0 ? std::string("Kael Vorn") : BladeName(who); }
static const char* GuildTaskLabel(const GameState::GuildMind& m) {
    switch (m.task) {
        case kGtGather: {
            if (!m.working || m.taskIdx < 0) return "Off to gather";
            int k = GuildGatherKind(kWildernessGatherNodes[m.taskIdx].resource);
            return k == 1 ? "Chopping wood" : (k == 3 ? "Fishing" : "Mining");
        }
        case kGtFarm: return m.working ? "Fighting monsters" : "Looking for a fight";
        case kGtRest: return m.working ? "Resting at camp" : "Heading to camp";
        case kGtSell: return "Taking loot to town";
        case kGtFlee: return "Fleeing!";
        case kGtEscort: return "Running with the champion";
        default: return "Roaming";
    }
}
static std::string GuildActivityText(GameState::RivalActivity a, const GameState::GuildMind& m) {
    if (a == GameState::RivalActivity::Hunting) return "Hunting...";
    if (a == GameState::RivalActivity::Stalking) return "Stalking...";
    return GuildTaskLabel(m);
}

// What they say. Kinds: 0 gather, 1 fishing, 2 farm kill, 3 kill-steal, 4 rest,
// 5 sell, 6 back on its feet, 7 notices you, 8 backs off, 9 flees, 10 gloats,
// 11 revenge, 12 cornered.
static const char* GuildLine(int who, int kind) {
    static const char* champ[13][3] = {
        { "Mine now. All of it.", "Quiet out here. Good.", "Every bit of this is coin." },
        { "Come on, bite...", "Better than fighting. Barely.", "Fish don't hit back." },
        { "Too easy.", "Next!", "Another one for the pile." },
        { "Hey! That one was MINE.", "Kill-stealer. I'll remember that.", "Oh, you want to play it that way?" },
        { "Need a breather...", "Patch up, then back out.", "Ow. Worth it." },
        { "Pack's full. Time to cash in.", "Off to town - don't touch my spots.", "Heavy pack, light heart." },
        { "Did you miss me?", "Back on my feet. Where were we?", "Can't keep a good red down." },
        { "Nice gear. Shame if something happened to it.", "I see you...", "Wander a little closer. Go on." },
        { "Not today.", "You got lucky. Next time.", "I'll catch you when you're weaker." },
        { "Enough! I'm out!", "This isn't over!", "You'll pay for this!" },
        { "Thanks for the gold.", "Stay down.", "Better luck next life." },
        { "Remember me? I remember YOU.", "Payback time!", "You should have stayed in town." },
        { "Fine. To the death, then!", "Cornered, am I? Come on!", "No more running." },
    };
    static const char* blade[13][2] = {
        { "Boss wants ore. Boss gets ore.", "Chop, chop." },
        { "Nothing's biting.", "Supper, maybe." },
        { "Heh.", "Easy coin." },
        { "Oi! That was ours!", "Murder Inc. doesn't share." },
        { "Need to patch up.", "Back to camp." },
        { "Hauling loot to town.", "Pack's full." },
        { "Murder Inc. doesn't stay down.", "Back again." },
        { "The boss would like to meet you.", "Look who's out alone." },
        { "Not against that. Not alone.", "Another time." },
        { "Run!", "Not worth dying for!" },
        { "Murder Inc. sends its regards.", "Stay down." },
        { "That's for the crew!", "You cut down one of ours." },
        { "Nowhere left to run. Fine!", "Come on then!" },
    };
    kind = std::clamp(kind, 0, 12);
    return who < 0 ? champ[kind][std::rand() % 3] : blade[kind][std::rand() % 2];
}
// Speech bubble + journal line - only when you're close enough to hear it.
static void GuildSay(GameState& s, int who, int kind, bool force = false) {
    GameState::GuildMind& m = GuildMindOf(s, who);
    Vector2 pos = GuildPosOf(s, who);
    if (!force && m.sayCooldown > 0.0f) return;
    if (s.screen != Screen::Wilderness || GuildAbsent(pos) || Dist(pos, s.wildernessPlayerPos) > 700.0f) return;
    m.say = GuildLine(who, kind);
    m.sayT = 3.5f;
    m.sayCooldown = 10.0f + RandUnit() * 10.0f;
    Journal(s, GuildWho(who) + ": \"" + m.say + "\"");
}

static Vector2 GuildCampPos(const GameState& s, int who) {
    Vector2 c = kRivalCampSpots[s.rivalCampIdx];
    if (who < 0) return c;
    float a = 1.3f + who * 2.1f;
    return { c.x + cosf(a) * 70.0f * kCampS, c.y + sinf(a) * 70.0f * kCampS };
}
static Vector2 GuildNearestGate(Vector2 p) {
    const Vector2 gates[4] = { kWildernessReturnGatePos, kWildernessTown2GatePos, kWildernessTown3GatePos, kWildernessTown4GatePos };
    Vector2 best = gates[0];
    for (const Vector2& g : gates) if (Dist(p, g) < Dist(p, best)) best = g;
    return best;
}
// Is this monster spot unavailable to a guild member (dead, yours, or a crewmate's)?
static bool GuildSpotTaken(const GameState& s, int spot, int self) {
    if (s.wildSpotRespawn[spot] > 0.0f) return true;
    if (s.wildEngaged.has_value() && !s.wildEngaged->isRival && s.wildEngaged->bladeIdx < 0 && s.wildEngaged->spotIdx == spot) return true;
    if (FindWildExtra(s, spot)) return true;
    for (const auto& d : s.dyingMonsters) if (d.zone == 0 && d.spotIdx == spot) return true;
    if (self != -1 && s.rivalMind.task == kGtFarm && s.rivalMind.taskIdx == spot) return true;
    for (int j = 0; j < kBladeCount; j++)
        if (j != self && s.blades[j].mind.task == kGtFarm && s.blades[j].mind.taskIdx == spot) return true;
    return false;
}
static bool GuildPlayerHasSpot(const GameState& s, int spot) {
    return (s.wildEngaged.has_value() && !s.wildEngaged->isRival && s.wildEngaged->bladeIdx < 0 && s.wildEngaged->spotIdx == spot) ||
           FindWildExtra(s, spot) != nullptr;
}
// Level growth from honest work, capped relative to you so it never runs away:
// the champion tops out a little above your power, blades well below it (and
// never above the champion).
static void GuildGrow(GameState& s, float& level, int who, float amt) {
    float power = (float)CombatPower(s);
    float cap = who < 0 ? std::max(16.0f, power * 1.15f) : std::min(std::max(5.0f, s.rivalLevel), std::max(8.0f, power * 0.6f));
    if (level < cap) level = std::min(cap, level + amt);
}

static void GuildPickTask(GameState& s, int who, float level) {
    GameState::GuildMind& m = GuildMindOf(s, who);
    Vector2 pos = GuildPosOf(s, who);
    m.working = false; m.taskIdx = -1; m.stuckT = 0.0f; m.stuckFrom = pos;
    if (m.hpFrac < 0.45f) { m.task = kGtRest; m.target = GuildCampPos(s, who); GuildSay(s, who, 4); return; }
    if (m.bag >= kGuildBagCap) { m.task = kGtSell; m.target = GuildNearestGate(pos); GuildSay(s, who, 5); return; }
    // Blades like to run with the boss now and then.
    if (who >= 0 && RandUnit() < 0.25f && !GuildAbsent(s.rivalPos) &&
        s.rivalActivity == GameState::RivalActivity::Patrol &&
        (s.rivalMind.task == kGtFarm || s.rivalMind.task == kGtGather || s.rivalMind.task == kGtWander) &&
        Dist(pos, s.rivalPos) < 1400.0f) {
        m.task = kGtEscort; m.taskT = 30.0f + RandUnit() * 30.0f; return;
    }
    Vector2 home = who < 0 ? pos : GuildCampPos(s, who);
    float range = who < 0 ? 1300.0f : 1000.0f;
    float roll = RandUnit();
    if (roll < 0.47f) { // farm a monster it can handle
        int best = -1; float bestScore = 1e9f;
        for (int i = 0; i < (int)kWildernessMonsterSpots.size(); i++) {
            const WildernessMonsterSpot& sp = kWildernessMonsterSpots[i];
            if ((float)sp.level > level * (who < 0 ? 1.15f : 1.3f) || sp.iconIdx == kWyrmIcon || i == kBreakoutSpot) continue;
            float d = Dist(home, sp.pos);
            if (d > range || GuildSpotTaken(s, i, who)) continue;
            float score = d * (0.6f + RandUnit()); // nearish, with some whim
            if (score < bestScore) { bestScore = score; best = i; }
        }
        if (best >= 0) { m.task = kGtFarm; m.taskIdx = best; m.target = kWildernessMonsterSpots[best].pos; return; }
    }
    if (roll < 0.88f) { // gather
        int best = -1; float bestScore = 1e9f;
        for (int i = 0; i < (int)kWildernessGatherNodes.size(); i++) {
            float d = Dist(home, kWildernessGatherNodes[i].pos);
            if (d > range) continue;
            bool busy = false;
            if (who != -1 && s.rivalMind.task == kGtGather && s.rivalMind.taskIdx == i) busy = true;
            for (int j = 0; j < kBladeCount; j++)
                if (j != who && s.blades[j].mind.task == kGtGather && s.blades[j].mind.taskIdx == i) busy = true;
            if (busy) continue;
            float score = d * (0.5f + RandUnit());
            if (score < bestScore) { bestScore = score; best = i; }
        }
        if (best >= 0) { m.task = kGtGather; m.taskIdx = best; m.target = kWildernessGatherNodes[best].pos; return; }
    }
    // wander: stretch the legs somewhere nearby that isn't water or a ridge
    for (int tries = 0; tries < 8; tries++) {
        float a = RandUnit() * 6.2831853f, r = 150.0f + RandUnit() * 350.0f;
        Vector2 t = ClampToWorld({ home.x + cosf(a) * r, home.y + sinf(a) * r }, 120.0f, kWildernessWorldSize);
        if (!WildBlocked(t)) { m.task = kGtWander; m.target = t; m.taskT = 3.0f + RandUnit() * 4.0f; return; }
    }
    m.task = kGtRest; m.target = GuildCampPos(s, who);
}

// Walk toward a point, sliding along water/ridges. 0 walking, 1 arrived, 2 stuck.
static bool GuildPathClear(Vector2 from, Vector2 dir, float look); // (with the wilderness solids)
// Chased home: the others in camp come out to meet you (two blades if they're
// there, else the champion). Seen with your own eyes - no Tracking roll.
static void GuildCampRally(GameState& s, int who) {
    Vector2 camp = kRivalCampSpots[s.rivalCampIdx];
    if (s.playerIsGhost || PlayerYoung(s) || Dist(s.wildernessPlayerPos, camp) > 520.0f) return;
    int first = -1, second = -1;
    for (int bi = 0; bi < kBladeCount; bi++) {
        if (bi == who) continue;
        auto& b = s.blades[bi];
        if (b.mind.downT > 0.0f || GuildAbsent(b.pos) || b.mind.hpFrac < 0.4f ||
            b.activity != GameState::RivalActivity::Patrol || Dist(b.pos, camp) > 420.0f) continue;
        if (first < 0) first = bi; else if (second < 0) second = bi;
    }
    if (first >= 0) {
        s.blades[first].mind.task = kGtNone;
        if (second >= 0) s.blades[second].mind.task = kGtNone;
        BladeStartHunt(s, first, second);
        GuildSay(s, first, 11, true);
    } else if (who >= 0 && s.rivalMind.downT <= 0.0f && !GuildAbsent(s.rivalPos) && s.rivalMind.hpFrac >= 0.4f &&
               s.rivalActivity == GameState::RivalActivity::Patrol && Dist(s.rivalPos, camp) < 420.0f) {
        s.rivalMind.task = kGtNone;
        RivalStartHunt(s);
        GuildSay(s, -1, 11, true);
    } else return;
    s.rivalBanner = "You followed it into Murder Inc.'s camp!";
    s.rivalBannerTimer = kRivalBannerTime;
    s.logLine = "You chased it right into Murder Inc.'s camp - they pour out to meet you!";
    PlaySfx(SfxId::Hunt);
}
static int GuildWalk(GameState::GuildMind& m, Vector2& pos, Vector2 target, float speed, float dt, float arrive) {
    Vector2 d = { target.x - pos.x, target.y - pos.y };
    float l = std::sqrt(d.x * d.x + d.y * d.y);
    if (l <= arrive) { m.stuckT = 0.0f; m.stuckFrom = pos; return 1; }
    Vector2 prev = pos;
    float step = std::min(l, speed * dt);
    pos.x += d.x / l * step; pos.y += d.y / l * step;
    if (!WildBlocked(prev)) WildTerrainResolve(pos, prev);
    m.stuckT += dt;
    if (m.stuckT >= 2.0f) { // made real progress in the last 2 s?
        bool stuck = Dist(pos, m.stuckFrom) < speed * 2.0f * 0.25f;
        m.stuckT = 0.0f; m.stuckFrom = pos;
        if (stuck) return 2;
    }
    return 0;
}

// Everything a guild member does when it isn't hunting you. who: -1 champion, else blade.
static void GuildLive(GameState& s, int who, float& level, float dt) {
    GameState::GuildMind& m = GuildMindOf(s, who);
    Vector2& pos = GuildPosOf(s, who);
    m.sayT -= dt; m.sayCooldown -= dt; m.huntCooldown -= dt * (s.guildWarOn[kGuildWarMurderInc] ? 1.8f : 1.0f); // at war: they come for you more often
    if (who < 0) s.rivalGrudge = std::max(0.0f, s.rivalGrudge - dt / 900.0f); // grudges fade over ~15 min each
    if (m.downT > 0.0f) { // beaten: out of the world until it recovers
        m.downT -= dt;
        pos = kGuildAbsentPos;
        if (m.downT <= 0.0f) {
            m.downT = 0.0f; m.hpFrac = 0.6f; m.cornered = false;
            pos = GuildCampPos(s, who);
            m.task = kGtRest; m.target = pos; m.working = true;
            m.lastPosValid = false;
            if (s.screen == Screen::Wilderness)
                Journal(s, "Word in the wilds: the " + GuildWho(who) + " is back on their feet.");
        }
        return;
    }
    if (m.task == kGtInTown) { // inside a town selling the haul
        m.taskT -= dt;
        pos = kGuildAbsentPos;
        if (m.taskT <= 0.0f) {
            m.gold += m.bag * 4 + 5; m.bag = 0; m.hpFrac = 1.0f;
            GuildGrow(s, level, who, 0.4f); // new kit from the proceeds
            pos = { m.target.x + (RandUnit() - 0.5f) * 80.0f, m.target.y + 70.0f };
            if (WildBlocked(pos)) pos = m.target;
            m.task = kGtNone; m.lastPosValid = false;
        }
        return;
    }
    if (GuildAbsent(pos)) { pos = GuildCampPos(s, who); m.lastPosValid = false; }
    bool resting = m.task == kGtRest && m.working;
    m.hpFrac = std::min(1.0f, m.hpFrac + dt / (resting ? 35.0f : 240.0f));
    if (m.hpFrac > 0.6f) m.cornered = false;
    if (m.task == kGtNone) GuildPickTask(s, who, level);
    Vector2 face = { 0, 0 }; bool faceSet = false;
    switch (m.task) {
        case kGtWander: {
            if (!m.working) {
                int r = GuildWalk(m, pos, m.target, kGuildWalkSpeed, dt, 30.0f);
                if (r == 1) m.working = true; else if (r == 2) m.task = kGtNone;
            } else if ((m.taskT -= dt) <= 0.0f) m.task = kGtNone;
            break;
        }
        case kGtGather: {
            const WildernessGatherNode& n = kWildernessGatherNodes[m.taskIdx];
            if (!m.working) {
                int r = GuildWalk(m, pos, n.pos, kGuildWalkSpeed, dt, 42.0f);
                if (r == 2 && Dist(pos, n.pos) < 150.0f) r = 1; // the bank of a fishing spot is close enough
                if (r == 1) {
                    m.working = true; m.taskT = 9.0f + RandUnit() * 7.0f;
                    GuildSay(s, who, GuildGatherKind(n.resource) == 3 ? 1 : 0);
                } else if (r == 2) m.task = kGtNone;
            } else {
                face = n.pos; faceSet = true;
                if ((m.taskT -= dt) <= 0.0f) { m.bag += 1 + std::rand() % 2; m.task = kGtNone; }
            }
            break;
        }
        case kGtFarm: {
            int i = m.taskIdx;
            if (GuildPlayerHasSpot(s, i)) { // you took its kill
                if (m.working || Dist(pos, WildernessMonsterLivePos(i, s.worldTime)) < 300.0f) GuildSay(s, who, 3, true);
                if (who < 0) s.rivalGrudge = std::min(5.0f, s.rivalGrudge + 0.25f);
                m.task = kGtNone; break;
            }
            if (s.wildSpotRespawn[i] > 0.0f) { m.task = kGtNone; break; }
            const WildernessMonsterSpot& sp = kWildernessMonsterSpots[i];
            Vector2 mp = WildernessMonsterLivePos(i, s.worldTime);
            if (!m.working) {
                int r = GuildWalk(m, pos, mp, kGuildWalkSpeed, dt, 50.0f);
                if (r == 1) {
                    m.working = true; m.swingT = 0.0f;
                    m.taskT = std::clamp(7.0f * (float)sp.level / std::max(1.0f, level), 4.0f, 16.0f);
                } else if (r == 2) m.task = kGtNone;
                break;
            }
            if (Dist(pos, mp) > 58.0f) GuildWalk(m, pos, mp, 60.0f, dt, 50.0f); // keep in reach as it shuffles
            face = mp; faceSet = true;
            m.swingT += dt;
            if (m.swingT >= kGuildSwingPeriod) { // trading blows costs it health
                m.swingT -= kGuildSwingPeriod;
                m.hpFrac -= std::clamp((float)sp.level / std::max(1.0f, level), 0.2f, 2.0f) * 0.02f;
            }
            if (m.hpFrac < 0.3f) { m.task = kGtRest; m.target = GuildCampPos(s, who); m.working = false; GuildSay(s, who, 4); break; }
            if ((m.taskT -= dt) <= 0.0f) { // the kill
                s.wildSpotRespawn[i] = RollWildRespawn();
                if (s.screen == Screen::Wilderness && Dist(mp, s.wildernessPlayerPos) < 1600.0f) {
                    GameState::DyingMonster dm;
                    dm.zone = 0; dm.pos = mp; dm.timer = dm.duration = kMonsterDeathAnimTime;
                    dm.spotIdx = i; dm.name = sp.name; dm.iconIdx = sp.iconIdx; dm.guildKill = true;
                    s.dyingMonsters.push_back(dm);
                }
                m.gold += sp.baseGold;
                if (sp.baseLeather > 0) m.bag += 1;
                GuildGrow(s, level, who, 0.15f * std::clamp((float)sp.level / std::max(1.0f, level), 0.3f, 1.5f));
                if (RandUnit() < 0.4f) GuildSay(s, who, 2);
                m.task = kGtNone;
            }
            break;
        }
        case kGtRest: {
            if (!m.working) {
                int r = GuildWalk(m, pos, m.target, kGuildWalkSpeed, dt, 30.0f);
                if (r != 0) m.working = true; // stuck on the way: rest where it stands
            } else if (m.hpFrac >= 0.97f) m.task = kGtNone;
            break;
        }
        case kGtSell: {
            int r = GuildWalk(m, pos, m.target, kGuildWalkSpeed, dt, 40.0f);
            if (r == 1) { m.task = kGtInTown; m.taskT = 35.0f + RandUnit() * 35.0f; pos = kGuildAbsentPos; }
            else if (r == 2) { m.target = GuildNearestGate({ pos.x + 300.0f, pos.y }); }
            break;
        }
        case kGtFlee: {
            // Fleeing (2026-09-27): it runs for camp but never back past you, steers
            // round trees, ridges and water instead of pinning itself against them,
            // opens with a sprint, binds its wounds as it goes - and if you chase it
            // all the way home, whoever is in camp comes out to meet you.
            Vector2 camp = GuildCampPos(s, who), me = s.wildernessPlayerPos;
            Vector2 toCamp = { camp.x - pos.x, camp.y - pos.y }, away = { pos.x - me.x, pos.y - me.y };
            float lc = std::max(1e-3f, hypotf(toCamp.x, toCamp.y)), la = std::max(1e-3f, hypotf(away.x, away.y));
            toCamp = { toCamp.x / lc, toCamp.y / lc }; away = { away.x / la, away.y / la };
            float k = (toCamp.x * away.x + toCamp.y * away.y) < 0.2f ? 1.6f : 0.35f;
            Vector2 want = { toCamp.x + away.x * k, toCamp.y + away.y * k };
            float lw = std::max(1e-3f, hypotf(want.x, want.y));
            want = { want.x / lw, want.y / lw };
            Vector2 dir = want;
            static const float kOffs[] = { 0.0f, 0.45f, -0.45f, 0.9f, -0.9f, 1.4f, -1.4f, 2.0f, -2.0f, 2.6f, -2.6f };
            for (float o : kOffs) {
                Vector2 d = { want.x * cosf(o) - want.y * sinf(o), want.x * sinf(o) + want.y * cosf(o) };
                if (GuildPathClear(pos, d, 64.0f)) { dir = d; break; }
            }
            float spd = m.taskT > 7.0f ? kPlayerSpeed * 1.1f : kGuildFleeSpeed; // an adrenaline burst first
            Vector2 prev = pos;
            pos.x += dir.x * spd * dt; pos.y += dir.y * spd * dt;
            if (!WildBlocked(prev)) WildTerrainResolve(pos, prev);
            m.hpFrac = std::min(1.0f, m.hpFrac + 0.012f * dt); // bandaging on the run
            m.taskT -= dt;
            bool home = Dist(pos, camp) < 70.0f;
            if (home) GuildCampRally(s, who);
            if (home || m.taskT <= 0.0f || Dist(pos, me) > 750.0f || s.screen != Screen::Wilderness) {
                m.task = kGtRest; m.target = camp; m.working = home;
            }
            break;
        }
        case kGtEscort: {
            m.taskT -= dt;
            bool bossBusy = GuildAbsent(s.rivalPos) || s.rivalActivity != GameState::RivalActivity::Patrol ||
                            (s.wildEngaged.has_value() && s.wildEngaged->isRival) || // duels stay 1v1: give the boss room
                            s.rivalMind.task == kGtFlee || s.rivalMind.task == kGtRest || s.rivalMind.task == kGtSell;
            if (bossBusy || m.taskT <= 0.0f) { m.task = kGtNone; break; }
            float a = s.rivalMind.yaw + 3.14159f + (who - 1) * 0.6f; // fanned out behind the boss
            Vector2 slot = { s.rivalPos.x + cosf(a) * 75.0f, s.rivalPos.y + sinf(a) * 75.0f };
            float d = Dist(pos, slot);
            GuildWalk(m, pos, slot, d > 200.0f ? 150.0f : 105.0f, dt, 18.0f);
            if (d < 40.0f && s.rivalMind.working) { face = s.rivalPos; faceSet = true; }
            break;
        }
        default: m.task = kGtNone; break;
    }
    // Facing: the work in hand, else the way it's walking.
    if (faceSet) {
        m.yaw = atan2f(face.y - pos.y, face.x - pos.x);
    } else if (m.lastPosValid) {
        float dx = pos.x - m.lastPos.x, dz = pos.y - m.lastPos.y;
        if (dx * dx + dz * dz > 0.04f) m.yaw = atan2f(dz, dx);
    }
    m.lastPos = pos; m.lastPosValid = true;
}

// The "do I jump them?" judgement, checked every few seconds while it's near.
static bool GuildWantsHunt(GameState& s, int who, float level, float dt) {
    GameState::GuildMind& m = GuildMindOf(s, who);
    Vector2& pos = GuildPosOf(s, who);
    m.thinkT -= dt;
    if (m.thinkT > 0.0f) return false;
    m.thinkT = kGuildThinkPeriod * (0.8f + 0.4f * RandUnit());
    if (s.screen != Screen::Wilderness || s.playerIsGhost || s.playerDeathAnimT > 0.0f || PlayerYoung(s)) return false;
    if (m.downT > 0.0f || GuildAbsent(pos) || m.task == kGtFlee || m.task == kGtInTown) return false;
    float d = Dist(pos, s.wildernessPlayerPos);
    if (d > (who < 0 ? kGuildSenseRange : kBladeSenseRange)) return false;
    // Weigh it up: its strength (blades count crewmates close by) against yours.
    float mine = level * std::max(0.1f, m.hpFrac);
    if (who >= 0)
        for (int j = 0; j < kBladeCount; j++)
            if (j != who && s.blades[j].mind.downT <= 0.0f && Dist(s.blades[j].pos, pos) < 500.0f)
                mine += s.blades[j].level * std::max(0.1f, s.blades[j].mind.hpFrac);
    float theirs = std::max(1.0f, (float)CombatPower(s)) * std::max(0.1f, (float)s.hp / std::max(1.0f, (float)s.maxHp));
    float odds = mine / theirs;
    bool vulnerable = s.gatheringResource.has_value() || s.wildEngaged.has_value() || (float)s.hp < (float)s.maxHp * 0.5f;
    bool nearSafety = Dist(s.wildernessPlayerPos, kWildernessReturnGatePos) < kRivalSafetyRadius ||
                      Dist(s.wildernessPlayerPos, kWildernessTown2GatePos) < kRivalSafetyRadius ||
                      Dist(s.wildernessPlayerPos, kWildernessTown3GatePos) < kRivalSafetyRadius ||
                      Dist(s.wildernessPlayerPos, kWildernessTown4GatePos) < kRivalSafetyRadius;
    for (const auto& e : kWildernessDungeonEntrances)
        if (Dist(s.wildernessPlayerPos, e.pos) < kRivalSafetyRadius) nearSafety = true;
    if (m.huntCooldown <= 0.0f && m.hpFrac >= 0.5f) {
        float c = who < 0 ? 0.11f : 0.07f;
        if (odds >= 1.3f) c *= 1.7f;
        else if (odds < 0.6f) c *= 0.1f;
        else if (odds < 0.9f) c *= 0.45f;
        if (vulnerable) c += 0.08f;
        if (who < 0) c += std::min(0.25f, s.rivalGrudge * 0.06f);
        if (d < 300.0f) c *= 1.5f; // you're right there
        if (nearSafety) c *= 0.3f;
        if (RandUnit() < c) return true;
    }
    // Didn't strike. Outmatched and you're close: it backs away from you.
    if ((odds < 0.6f || m.hpFrac < 0.5f) && d < 350.0f && m.task != kGtRest && m.task != kGtSell) {
        Vector2 away = { pos.x - s.wildernessPlayerPos.x, pos.y - s.wildernessPlayerPos.y };
        float al = std::max(1.0f, std::sqrt(away.x * away.x + away.y * away.y));
        Vector2 t = ClampToWorld({ pos.x + away.x / al * 550.0f, pos.y + away.y / al * 550.0f }, 120.0f, kWildernessWorldSize);
        m.task = kGtWander; m.target = t; m.working = false; m.taskT = 4.0f; m.stuckT = 0.0f; m.stuckFrom = pos;
        GuildSay(s, who, 8);
    } else if (d < 450.0f && RandUnit() < 0.3f) {
        GuildSay(s, who, 7);
    }
    return false;
}

// For drawing: is a guild member mid-fight with this monster spot?
static bool GuildFarmingSpot(const GameState& s, int spot, Vector2* who, float* swingT) {
    auto check = [&](const GameState::GuildMind& m, Vector2 p, GameState::RivalActivity a) {
        if (a != GameState::RivalActivity::Patrol || m.task != kGtFarm || !m.working || m.taskIdx != spot || GuildAbsent(p)) return false;
        *who = p; *swingT = m.swingT; return true;
    };
    if (!(s.wildEngaged.has_value() && s.wildEngaged->isRival) && check(s.rivalMind, s.rivalPos, s.rivalActivity)) return true;
    for (int j = 0; j < kBladeCount; j++)
        if (!(s.wildEngaged.has_value() && s.wildEngaged->bladeIdx == j) && check(s.blades[j].mind, s.blades[j].pos, s.blades[j].activity)) return true;
    return false;
}
// The guild keeps living while you're in town, a dungeon or a menu - no hunting
// then (they can't see you), and a hunt in progress is called off.
static void UpdateGuildOffscreen(GameState& s, float dt) {
    if (s.screen == Screen::Wilderness) return;
    if (s.rivalActivity != GameState::RivalActivity::Patrol) {
        s.rivalActivity = GameState::RivalActivity::Patrol; s.rivalMind.task = kGtNone; s.rivalMind.huntCooldown = 30.0f;
    }
    GuildLive(s, -1, s.rivalLevel, dt);
    for (int bi = 0; bi < kBladeCount; bi++) {
        auto& b = s.blades[bi];
        if (b.activity != GameState::RivalActivity::Patrol) {
            b.activity = GameState::RivalActivity::Patrol; b.mind.task = kGtNone; b.mind.huntCooldown = 30.0f;
        }
        b.autoEngage = false;
        GuildLive(s, bi, b.level, dt);
    }
    s.rivalAutoEngage = false;
}

static void UpdateRivalRoaming(GameState& s, float dt) {
    if (s.wildEngaged.has_value() && s.wildEngaged->isRival) return;
    // Ghosts are beneath the red's notice - break off any hunt/stalk, patrol instead.
    // Young players too (2026-09-27): nobody hunts a character still learning the ropes.
    if (s.playerIsGhost || s.playerDeathAnimT > 0.0f || PlayerYoung(s)) {
        if (s.rivalActivity == GameState::RivalActivity::Hunting ||
            s.rivalActivity == GameState::RivalActivity::Stalking) {
            s.rivalActivity = GameState::RivalActivity::Patrol;
            s.rivalActivityTimer = 0.0f;
            s.rivalMind.task = kGtNone;
        }
        GuildLive(s, -1, s.rivalLevel, dt); // life goes on while you're a ghost
        return;
    }

    // Smoothed player velocity for intercept steering. Movement runs after this in
    // DrawWildernessScreen, so this is one frame stale - fine for prediction.
    // Teleport guard: gate travel zeroes it instead of whipping the intercept.
    if (dt > 0.0001f) {
        Vector2 d = { s.wildernessPlayerPos.x - s.rivalPrevPlayerPos.x,
                      s.wildernessPlayerPos.y - s.rivalPrevPlayerPos.y };
        float dl = std::sqrt(d.x * d.x + d.y * d.y);
        if (dl > kRivalTeleportGuard) {
            s.rivalPlayerVel = { 0, 0 };
        } else {
            Vector2 inst = { d.x / dt, d.y / dt };
            float a = std::min(1.0f, kRivalVelSmooth * dt);
            s.rivalPlayerVel.x += (inst.x - s.rivalPlayerVel.x) * a;
            s.rivalPlayerVel.y += (inst.y - s.rivalPlayerVel.y) * a;
        }
    }
    s.rivalPrevPlayerPos = s.wildernessPlayerPos;

    // --- Stalking: visibly shadow the player at range, then commit or break off ---
    // Pure dread - no damage during the stalk, just the label and the banner.
    if (s.rivalActivity == GameState::RivalActivity::Stalking) {
        s.rivalStalkTimer -= dt;
        Vector2 away = { s.rivalPos.x - s.wildernessPlayerPos.x, s.rivalPos.y - s.wildernessPlayerPos.y };
        float alen = std::sqrt(away.x * away.x + away.y * away.y);
        if (alen > 0.0001f) {
            Vector2 target = { s.wildernessPlayerPos.x + away.x / alen * kRivalStalkRange,
                               s.wildernessPlayerPos.y + away.y / alen * kRivalStalkRange };
            Vector2 to = { target.x - s.rivalPos.x, target.y - s.rivalPos.y };
            float tl = std::sqrt(to.x * to.x + to.y * to.y);
            if (tl > kRivalArrivalRadius) {
                s.rivalPos.x += to.x / tl * kRivalStalkSpeed * dt;
                s.rivalPos.y += to.y / tl * kRivalStalkSpeed * dt;
            }
        }
        if (s.rivalStalkTimer <= 0.0f) {
            if (RandUnit() < 0.5f) RivalStartHunt(s); // commits - the banner fires
            else {
                s.rivalActivity = GameState::RivalActivity::Patrol; s.rivalActivityTimer = 0.0f;
                s.rivalMind.task = kGtNone; s.rivalMind.huntCooldown = 40.0f + RandUnit() * 40.0f;
            }
        }
        return;
    }

    // --- Hunting: intercept course, sprint/recover gait, catch ---
    if (s.rivalActivity == GameState::RivalActivity::Hunting) {
        s.rivalActivityTimer -= dt;
        // Gait machine: alternate sprint (faster than the player) and recover.
        s.rivalSprintTimer -= dt;
        if (s.rivalSprintTimer <= 0.0f) {
            s.rivalSprinting = !s.rivalSprinting;
            s.rivalSprintTimer = s.rivalSprinting ? kRivalSprintDuration : kRivalRecoverDuration;
            if (s.rivalSprinting) {
                s.rivalSprintStartDist = Dist(s.rivalPos, s.wildernessPlayerPos);
                s.rivalSprintStartVel = s.rivalPlayerVel;
            }
        }
        float distNow = Dist(s.rivalPos, s.wildernessPlayerPos);
        float speed = s.rivalSprinting ? kRivalSprintSpeed : kRivalRecoverSpeed;
        if (s.rivalSprinting && s.rivalSprintTimer < kRivalSprintDuration - kRivalSprintStuckTime) {
            // Break the sprint when juked or blocked: barely closing distance, or
            // the player sharply reversed direction since the sprint began.
            bool stuck = (s.rivalSprintStartDist - distNow) < kRivalSprintStuckEps;
            float cv = std::sqrt(s.rivalPlayerVel.x * s.rivalPlayerVel.x + s.rivalPlayerVel.y * s.rivalPlayerVel.y);
            float sv = std::sqrt(s.rivalSprintStartVel.x * s.rivalSprintStartVel.x +
                                 s.rivalSprintStartVel.y * s.rivalSprintStartVel.y);
            bool juked = false;
            if (cv > 60.0f && sv > 60.0f) {
                float dot = (s.rivalPlayerVel.x * s.rivalSprintStartVel.x +
                             s.rivalPlayerVel.y * s.rivalSprintStartVel.y) / (cv * sv);
                juked = dot < -0.15f; // turned >~99 degrees since the sprint began
            }
            if (stuck || juked) { s.rivalSprinting = false; s.rivalSprintTimer = kRivalRecoverDuration; }
        }
        // Intercept: steer toward where the player WILL be, not where they are -
        // juking matters, bee-lining doesn't.
        float tti = distNow / std::max(1.0f, speed);
        Vector2 predicted = { s.wildernessPlayerPos.x + s.rivalPlayerVel.x * tti,
                              s.wildernessPlayerPos.y + s.rivalPlayerVel.y * tti };
        predicted = ClampToWorld(predicted, kPlayerEdgeMargin, kWildernessWorldSize);
        Vector2 dir = { predicted.x - s.rivalPos.x, predicted.y - s.rivalPos.y };
        float len = std::sqrt(dir.x * dir.x + dir.y * dir.y);
        if (len > 0.0001f) {
            s.rivalPos.x += dir.x / len * speed * dt;
            s.rivalPos.y += dir.y / len * speed * dt;
        }
        // Caught you - the red doesn't ask for a duel. DrawWildernessScreen
        // converts the flag into a real fight if you're still in range.
        if (Dist(s.rivalPos, s.wildernessPlayerPos) < kRivalCatchRange) {
            s.rivalAutoEngage = true;
            return;
        }
        // Give up and go back to patrolling if the hunt times out.
        if (s.rivalActivityTimer <= 0.0f) {
            s.rivalActivity = GameState::RivalActivity::Patrol;
            s.rivalMind.task = kGtNone; s.rivalMind.huntCooldown = 40.0f + RandUnit() * 40.0f;
        }
        return;
    }
    // Not hunting: live (gather, farm, rest, sell - see GuildLive), and every few
    // seconds weigh up whether you're worth jumping (GuildWantsHunt). Murder Inc.
    // coordination (2026-09-24) still holds: one threat at a time - the champion is
    // a solo predator and won't pile onto a blade's hunt.
    GuildLive(s, -1, s.rivalLevel, dt);
    s.rivalPatrolTarget = s.rivalMind.target;
    if (GuildWantsHunt(s, -1, s.rivalLevel, dt) && !GuildThreatActive(s)) {
        s.rivalMind.task = kGtNone; s.rivalMind.working = false;
        if (s.rivalGrudge >= 1.0f) GuildSay(s, -1, 11, true);
        if (RandUnit() < kRivalStalkChance) RivalStartStalk(s);
        else RivalStartHunt(s);
    }
}

// Murder Inc. guild blade roaming (2026-09-24) - the champion's crew. Same
// patrol/hunt/stalk shape as UpdateRivalRoaming (same waypoint fiction, same
// intercept steering off the shared smoothed player velocity) but simpler:
// flat hunt speed (no sprint bursts), shorter leash, half the appetite, and the
// pair-hunt roll that makes two blades jump you at once. Called once per frame
// per blade from DrawWildernessScreen, right after UpdateRivalRoaming (which owns
// the shared s.rivalPlayerVel tracking the blades read).
static void UpdateBladeRoaming(GameState& s, int bi, float dt) {
    auto& b = s.blades[bi];
    if (s.wildEngaged.has_value() && s.wildEngaged->bladeIdx == bi) return;
    // Same ghost rule as the champion - the crew doesn't hunt the dead (or the Young) either.
    if (s.playerIsGhost || s.playerDeathAnimT > 0.0f || PlayerYoung(s)) {
        if (b.activity == GameState::RivalActivity::Hunting ||
            b.activity == GameState::RivalActivity::Stalking) {
            b.activity = GameState::RivalActivity::Patrol;
            b.activityTimer = 0.0f;
            b.mind.task = kGtNone;
        }
        GuildLive(s, bi, b.level, dt);
        return;
    }

    // --- Stalking: shadow the player at range, then commit (solo) or break off ---
    if (b.activity == GameState::RivalActivity::Stalking) {
        b.stalkTimer -= dt;
        Vector2 away = { b.pos.x - s.wildernessPlayerPos.x, b.pos.y - s.wildernessPlayerPos.y };
        float alen = std::sqrt(away.x * away.x + away.y * away.y);
        if (alen > 0.0001f) {
            Vector2 target = { s.wildernessPlayerPos.x + away.x / alen * kBladeStalkRange,
                               s.wildernessPlayerPos.y + away.y / alen * kBladeStalkRange };
            Vector2 to = { target.x - b.pos.x, target.y - b.pos.y };
            float tl = std::sqrt(to.x * to.x + to.y * to.y);
            if (tl > kRivalArrivalRadius) {
                b.pos.x += to.x / tl * kRivalStalkSpeed * dt;
                b.pos.y += to.y / tl * kRivalStalkSpeed * dt;
            }
        }
        if (b.stalkTimer <= 0.0f) {
            if (RandUnit() < 0.5f) BladeStartHunt(s, bi, -1); // commits solo - pairs only form on fresh patrol commits
            else {
                b.activity = GameState::RivalActivity::Patrol; b.activityTimer = 0.0f;
                b.mind.task = kGtNone; b.mind.huntCooldown = 40.0f + RandUnit() * 40.0f;
            }
        }
        return;
    }

    // --- Hunting: intercept course at a flat, outrunnable speed ---
    if (b.activity == GameState::RivalActivity::Hunting) {
        b.activityTimer -= dt;
        float distNow = Dist(b.pos, s.wildernessPlayerPos);
        float tti = distNow / kBladeHuntSpeed;
        Vector2 predicted = { s.wildernessPlayerPos.x + s.rivalPlayerVel.x * tti,
                              s.wildernessPlayerPos.y + s.rivalPlayerVel.y * tti };
        predicted = ClampToWorld(predicted, kPlayerEdgeMargin, kWildernessWorldSize);
        Vector2 dir = { predicted.x - b.pos.x, predicted.y - b.pos.y };
        float len = std::sqrt(dir.x * dir.x + dir.y * dir.y);
        if (len > 0.0001f) {
            b.pos.x += dir.x / len * kBladeHuntSpeed * dt;
            b.pos.y += dir.y / len * kBladeHuntSpeed * dt;
        }
        if (Dist(b.pos, s.wildernessPlayerPos) < kRivalCatchRange) {
            b.autoEngage = true;
            return;
        }
        if (b.activityTimer <= 0.0f) {
            b.activity = GameState::RivalActivity::Patrol;
            b.mind.task = kGtNone; b.mind.huntCooldown = 40.0f + RandUnit() * 40.0f;
        }
        return;
    }

    // --- Living: gather, farm, rest, sell, run with the boss (GuildLive), and weigh
    // up a hunt every few seconds (GuildWantsHunt). One threat at a time: never
    // while the champion is on the prowl, never while another blade is hunting -
    // pairs form ONLY via the pair roll below.
    GuildLive(s, bi, b.level, dt);
    b.patrolTarget = b.mind.target;
    if (GuildWantsHunt(s, bi, b.level, dt) && !GuildThreatActive(s, bi)) {
        b.mind.task = kGtNone; b.mind.working = false;
        if (RandUnit() < kBladeStalkChance) { BladeStartStalk(s, bi); return; }
        // Pair hunt - the signature Murder Inc. jump: 30% chance a second blade
        // joins the same hunt. Only a blade that's up, idle, and within reach of
        // you can be pulled in; the champion never pair-hunts.
        int partner = -1;
        if (RandUnit() < kBladePairChance) {
            for (int j = 0; j < kBladeCount; j++) {
                if (j == bi) continue;
                const auto& bj = s.blades[j];
                if (bj.activity != GameState::RivalActivity::Patrol) continue;
                if (s.wildEngaged.has_value() && s.wildEngaged->bladeIdx == j) continue;
                if (bj.mind.downT > 0.0f || GuildAbsent(bj.pos) || bj.mind.task == kGtFlee || bj.mind.hpFrac < 0.5f) continue;
                if (Dist(bj.pos, s.wildernessPlayerPos) > 1100.0f) continue;
                partner = j;
                s.blades[j].mind.task = kGtNone;
                break;
            }
        }
        BladeStartHunt(s, bi, partner);
    }
}

// ---------------------------------------------------------------------
// Dungeon room layouts - real rooms and corridors, one distinct shape per dungeon
// (piloted on the Sunken Crypt alone as a single hub-and-spoke shape; once that held
// up, each other dungeon got its own shape instead of reusing it everywhere). All
// axis-aligned, like every other world layout in this file; anything not inside one of
// a dungeon's rectangles is solid wall, enforced as a simple hard movement stop with
// axis-slide fallback in DrawHuntScreen. Same order as kDungeons (0=Whisper Crypt,
// 1=The Weavers' Nest, 2=Sunken Vault, 3=Ember Depths, 4=Frostbound Tomb, 5=The Hollow).
//
//   The Weavers' Nest (Phase 5): a web-choked nest - big central chamber with 4 chambers opening directly onto it
//     (no corridor for those - the rectangles just share a wall) plus 2 further
//     chambers - an open raider stronghold rather than a maze.
//   The Sunken Crypt: the original hub-and-spoke pilot layout, unchanged.
//   The Sunken Vault: an asymmetric branching tree (not a star or a chain) with varied
//     room sizes - a more organic cave-system feel than the other three's uniform rooms.
// ---------------------------------------------------------------------
// Every rectangle below is exactly 2x the original (pre-2026-09-19) coordinates, to
// match kDungeonWorldSize going from 900 to 1800 - doubling every room/corridor
// preserves all the touching-boundary adjacency between them exactly (linear scaling
// can't introduce a gap or overlap that wasn't already there), while giving 4x the
// floor area and much longer walks between rooms to actually explore.
static const std::vector<Rectangle> kDungeonRoomLayouts[6] = {
    // [0] The Whisper Crypt - hub and spoke (the original pilot layout)
    {
        {760,760,280,280},    // hub
        {720,240,360,360},    // N room (monster 0)
        {810,600,180,160},    // N corridor (hub <-> N room)
        {720,1200,360,360},   // S room (monster 1)
        {810,1040,180,160},   // S corridor (hub <-> S room)
        {1200,720,360,360},   // E room (monster 2)
        {1040,810,160,180},   // E corridor (hub <-> E room)
        {240,720,360,360},    // W room (monster 3)
        {600,810,160,180},    // W corridor (hub <-> W room)
        {1300,160,320,320},   // NE room (monster 4)
        {1080,270,220,180},   // NE corridor (N room <-> NE room)
        {1260,1260,340,340},  // SE room (boss)
        {1080,1320,180,180},  // SE corridor (S room <-> SE room)
    },
    // [1] The Weavers' Nest (Phase 5) - web-choked nest chambers (fortress courtyard layout kept)
    {
        {600,600,600,600},    // courtyard (hub, no monster)
        {700,1200,400,300},   // South chamber (monster 0, spawn)
        {700,300,400,300},    // North chamber (monster 1)
        {1200,700,300,400},   // East chamber (monster 2)
        {300,700,300,400},    // West chamber (monster 3)
        {1200,300,400,400},   // NE chamber (monster 4)
        {1200,1100,440,440},  // SE chamber (boss)
    },
    // [2] The Sunken Vault - asymmetric branching cave
    {
        {740,1160,360,320},   // entrance (monster 0, spawn)
        {260,1180,360,280},   // room (monster 1)
        {620,1250,120,140},   // corridor
        {760,680,320,320},    // room (monster 2)
        {840,1000,160,160},   // corridor
        {760,240,320,320},    // room (monster 3)
        {840,560,160,120},    // corridor
        {1200,680,340,320},   // room (monster 4)
        {1080,760,120,160},   // corridor
        {1200,1120,400,360},  // boss room
        {1300,1000,160,120},  // corridor
    },
    // [3] The Ember Depths (Phase 4) - a volcanic forge: entry shaft, twin
    // forge halls, slag pit and magma channel, the Emberlord's Crucible below.
    {
        {780,1240,240,240},  // entry shaft (monster 0, spawn) - contains {900,1360}
        {780,960,240,280},   // forge hall 1 (monster 1) - touches entry's top edge
        {400,960,380,280},   // west slag pit (monster 2) - touches forge hall 1's west edge
        {1020,960,380,280},  // east magma channel (monster 3) - touches forge hall 1's east edge
        {780,680,240,280},   // forge hall 2 (monster 4) - touches forge hall 1's top edge
        {700,300,400,380},   // the Crucible (boss) - touches forge hall 2's top edge
    },
    // [4] The Frostbound Tomb (Phase 3) - a long frozen nave with side chapels,
    // the Frostbound King's throne at the far end. Rooms touch at clean
    // boundaries (nest-style: big chamber, no separate corridor rects).
    {
        {780,1240,240,240},  // entrance (monster 0, spawn) - contains {900,1360}
        {780,960,240,280},   // nave 1 (monster 1) - touches entrance's top edge
        {400,960,380,280},   // west chapel (monster 2) - touches nave 1's west edge
        {1020,960,380,280},  // east chapel (monster 3) - touches nave 1's east edge
        {780,680,240,280},   // nave 2 (monster 4) - touches nave 1's top edge
        {700,300,400,380},   // throne room (boss) - touches nave 2's top edge
    },
    // [5] The Hollow (Phase 5) - a lightless abyss shaft with two side tunnels, boss at the
    // very top (deepest point). Rooms are directly adjacent/overlapping by a clean 30px
    // (nest-style: big chamber, no separate corridor rects) rather than connected by corridors
    // like the other dungeons - a different construction technique for a genuinely
    // different shape. Every adjacency below was hand-verified to overlap, not just touch.
    {
        {750,1150,300,300},  // entrance (monster 0, spawn) - contains {900,1300}
        {750,880,300,300},   // shaft room 2 (monster 1) - overlaps entrance's top edge by 30
        {360,890,420,280},   // west tunnel (monster 2) - overlaps shaft room 2's west edge by 30
        {1020,890,420,280},  // east tunnel (monster 3) - overlaps shaft room 2's east edge by 30
        {750,610,300,300},   // shaft room 3 (monster 4) - overlaps shaft room 2's top edge by 30
        {680,240,440,400},   // boss room - overlaps shaft room 3's top edge by 30
    }
};
static bool DungeonIsFloor(int dungeonIdx, Vector2 p) {
    for (const Rectangle& r : kDungeonRoomLayouts[dungeonIdx])
        if (p.x >= r.x && p.x <= r.x + r.width && p.y >= r.y && p.y <= r.y + r.height) return true;
    return false;
}

// World positions for a dungeon's monster nodes - the center of that dungeon's own
// rooms in kDungeonRoomLayouts above (indices 0-4 = monsters 0-4, index 5 = boss).
static Vector2 DungeonMonsterNodePos(int dungeonIdx, int idx) {
    // Doubled to match kDungeonRoomLayouts (see that array's comment).
    // 9 slots per dungeon (kDungeonSlotCount): 0-7 regular, 8 boss. Slots 5-7 are
    // extra spawns (2026-09-24) placed as second monsters in the larger rooms so
    // respawn timers don't empty the dungeon; they reuse monster types 0-2.
    static const Vector2 kCenters[6][kDungeonSlotCount] = {
        { {900,420}, {900,1380}, {1380,900}, {420,900}, {1460,320}, {900,900}, {1040,420}, {1240,900}, {1430,1430} }, // [0] The Whisper Crypt
        { {900,1350}, {900,450}, {1350,900}, {450,900}, {1400,500}, {750,750}, {1050,1050}, {1050,450}, {1420,1320} }, // [1] The Weavers' Nest
        { {920,1320}, {440,1320}, {920,840}, {920,400}, {1370,840}, {1060,1320}, {1060,840}, {1230,840}, {1400,1300} }, // [2] The Sunken Vault
        { {900,1360}, {900,1100}, {590,1100}, {1210,1100}, {900,820}, {700,1100}, {1100,1100}, {1000,820}, {900,490} }, // [3] The Ember Depths
        { {900,1360}, {900,1100}, {590,1100}, {1210,1100}, {900,820}, {700,1100}, {1100,1100}, {1000,820}, {900,490} }, // [4] The Frostbound Tomb
        { {900,1300}, {900,1030}, {570,1030}, {1230,1030}, {900,760}, {1020,1300}, {1020,1030}, {450,1030}, {900,440} }, // [5] The Hollow
    };
    static_assert(kDungeonSlotCount == 9, "kCenters must have kDungeonSlotCount entries per dungeon");
    return kCenters[dungeonIdx][std::clamp(idx, 0, kDungeonBossSlot)];
}

// Monsters wander in a small loop around their home spot rather than standing frozen -
// a stateless, time-driven offset (no per-monster position to save/track) so it works
// identically for rendering, interaction range, and collision with zero extra bookkeeping.
// Each slot gets its own phase/speed/radius so they don't all move in lockstep. The
// Sunken Crypt's rooms are at least 160 units across against a <=28-unit wander radius,
// so monsters stay comfortably inside their room without needing room-aware clamping.
static Vector2 MonsterWanderOffset(int slotIdx, float worldTime) {
    float phase = (float)slotIdx * 2.4f; // arbitrary per-slot offset so motion isn't synchronized
    float speed = 0.5f + 0.15f * (slotIdx % 3);   // slight per-slot speed variety
    float radius = 22.0f + 6.0f * (slotIdx % 2);   // small wander radius - stays near its spawn
    return { std::cos(worldTime * speed + phase) * radius, std::sin(worldTime * speed * 0.8f + phase) * radius };
}
// The analytical derivative of MonsterWanderOffset (same phase/speed constants), giving
// a real facing direction for anything drawn wandering by it - used for Town NPCs
// (2026-09-23) so they visibly turn to face their own wander motion instead of always
// facing Down, without needing a stored previous-position field to compute velocity
// from. Not used for dungeon-monster/creature wander (those stay a simpler static Idle,
// see the Carl-art integration phase 4 notes) - Town is the one place players actually
// stand around watching NPCs long enough for it to be worth the extra polish.
static Vector2 WanderFacing(int slotIdx, float worldTime) {
    float phase = (float)slotIdx * 2.4f;
    float speed = 0.5f + 0.15f * (slotIdx % 3);
    Vector2 vel = { -std::sin(worldTime * speed + phase) * speed, std::cos(worldTime * speed * 0.8f + phase) * speed * 0.8f };
    float len = std::sqrt(vel.x * vel.x + vel.y * vel.y);
    return len > 0.0001f ? Vector2{ vel.x / len, vel.y / len } : Vector2{ 0, 1 };
}
static Vector2 DungeonMonsterLivePos(int dungeonIdx, int idx, float worldTime) {
    Vector2 home = DungeonMonsterNodePos(dungeonIdx, idx);
    Vector2 off = MonsterWanderOffset(idx, worldTime);
    return { home.x + off.x, home.y + off.y };
}
// Same wander treatment for Wilderness monster spots (added 2026-09-22 for live
// combat's bump-to-engage - see kWildernessMonsterSpots) - these previously stood
// completely still at kWildernessMonsterSpots[idx].pos until engaged.
static Vector2 WildernessMonsterLivePos(int idx, float worldTime) {
    Vector2 home = kWildernessMonsterSpots[idx].pos;
    Vector2 off = MonsterWanderOffset(idx, worldTime);
    return { home.x + off.x, home.y + off.y };
}
// Same idea for the roaming Innocent NPCs (kWildernessInnocentSpots) - a small wander
// in place, not a real patrol like the Rival, since these are meant to read as ordinary
// travelers rather than a threat with somewhere to be.
static Vector2 WildernessInnocentLivePos(int idx, float worldTime) {
    Vector2 home = kWildernessInnocentSpots[idx].pos;
    Vector2 off = MonsterWanderOffset(idx, worldTime);
    return { home.x + off.x, home.y + off.y };
}
// Same idea for Town's wandering NPCs (kTownNPCs) - Town's first-ever ambient motion.
static Vector2 TownNPCLivePos(int idx, float worldTime, int townIdx = 0) {
    Vector2 home = ActiveTownNPCs(townIdx)[idx].homePos;
    Vector2 off = MonsterWanderOffset(idx, worldTime);
    return { home.x + off.x, home.y + off.y };
}

// World positions for the Bloodstained Road's three ladders - one node per path (each
// node's target updates live as you climb, rather than one node per tier).
static Vector2 BloodstainedPathNodePos(int pathIdx) {
    static const Vector2 kPos[3] = { {220, 300}, {450, 550}, {680, 300} }; // blue, gray, red
    return kPos[std::clamp(pathIdx, 0, 2)];
}

static void DrawWorldNode(Vector2 screenPos, float radius, Color color, const std::string& label,
                            bool nearPlayer, const std::string& sublabel = "",
                            const Texture2D* icon = nullptr, Color iconTint = WHITE,
                            const Rectangle* iconSrcRect = nullptr) {
    bool onScreen = screenPos.x > kViewport.x - radius && screenPos.x < kViewport.x + kViewport.width + radius &&
                     screenPos.y > kViewport.y - radius && screenPos.y < kViewport.y + kViewport.height + radius;
    if (!onScreen) return;
    if (icon) {
        // Real art loaded (every dungeon monster) - show it directly with no colored
        // circle backdrop (a flat color disc behind the art was both visual clutter and
        // the actual source of the original red-on-red problem on the Ember Depths'
        // fire-red floor, since that disc used the monster's own color). A thin gold
        // ring still signals "in range", the same role it plays on buildings.
        if (nearPlayer) DrawCircleLines((int)screenPos.x, (int)screenPos.y, radius + 4, Fade(kColorSlate, 0.9f));
        // The neutral backing plate that used to sit here was removed 2026-09-23 at
        // Mark's request ("remove the circle behind all of the images") - it existed to
        // guarantee icon contrast against busy/similarly-colored floors (originally
        // fixed the Ember Depths' red fire-elemental icons blending into its red/near-
        // black lava floor). Now that most icons here are real art with their own
        // outlines/shading rather than flat single-color glyphs, that risk is lower, but
        // if a specific icon becomes hard to read against a specific floor again, this
        // is the spot to revisit rather than a new bug to chase elsewhere.
        // `iconSrcRect` (2026-09-23, animated monsters/creatures) crops one frame out of
        // a DirSpriteSheet via ActorSrcRect instead of showing the whole texture - same
        // ring/plate/label chrome either way.
        if (iconSrcRect) DrawIconCenteredRect(*icon, *iconSrcRect, screenPos, radius * 1.5f, iconTint);
        else DrawIconCentered(*icon, screenPos, radius * 1.5f, iconTint);
        int tw = MeasureUIText(label.c_str(), 13);
        DrawUIText(label.c_str(), (int)screenPos.x - tw / 2, (int)(screenPos.y + radius + 4), 13, kColorText);
        if (!sublabel.empty()) {
            int stw = MeasureUIText(sublabel.c_str(), 11);
            DrawUIText(sublabel.c_str(), (int)screenPos.x - stw / 2, (int)(screenPos.y + radius + 16), 11, Fade(kColorText, 0.85f));
        }
    } else {
        // No art loaded for this one (e.g. the Bloodstained Road's path markers, which
        // never pass an icon) - the colored circle is the only visual, so it still needs
        // the always-visible outline for contrast against similarly-colored ground.
        DrawCircleV(screenPos, radius, Fade(color, 0.85f));
        DrawCircleV(screenPos, radius, Fade(BLACK, nearPlayer ? 0.0f : 0.15f)); // subtle dim when out of range
        if (nearPlayer) {
            DrawCircleV(screenPos, radius + 3, Fade(kColorSlate, 0.9f));
            DrawCircleV(screenPos, radius, Fade(color, 0.9f));
        }
        DrawCircleLines((int)screenPos.x, (int)screenPos.y, radius, Fade(RAYWHITE, 0.9f));
        DrawCircleLines((int)screenPos.x, (int)screenPos.y, radius - 1, Fade(BLACK, 0.5f));
        int tw = MeasureUIText(label.c_str(), 13);
        DrawUIText(label.c_str(), (int)screenPos.x - tw / 2, (int)screenPos.y - 6, 13, RAYWHITE);
        if (!sublabel.empty()) {
            int stw = MeasureUIText(sublabel.c_str(), 11);
            DrawUIText(sublabel.c_str(), (int)screenPos.x - stw / 2, (int)screenPos.y + 7, 11, Fade(RAYWHITE, 0.85f));
        }
    }
}


// Simple clickable button helper.
// Tap shield (2026-09-26): while a floating panel (the 3D MENU dropdown) is
// open, buttons drawn earlier in the frame underneath it must not take the
// tap too. The panel's own buttons set g_uiShieldBypass while drawing.
static Rectangle g_uiShield = { 0, 0, 0, 0 };
static bool g_uiShieldOn = false, g_uiShieldBypass = false;
// Every button registers where it was drawn (2026-09-28, #57): a tap on any of
// them - or just beside one - never also counts as a tap on the world below
// (tap to walk, flag, Teleport). The list from the last frame is what counts.
static std::vector<Rectangle> g_uiRects, g_uiRectsPrev;
static std::vector<Rectangle> g_uiClips;
static bool g_uiClickTaken = false, g_uiGestureOwned = false;
static Rectangle UIClipped(Rectangle r) {
    for (const Rectangle& clip : g_uiClips) {
        float right = std::min(r.x + r.width, clip.x + clip.width);
        float bottom = std::min(r.y + r.height, clip.y + clip.height);
        r.x = std::max(r.x, clip.x); r.y = std::max(r.y, clip.y);
        r.width = std::max(0.0f, right - r.x); r.height = std::max(0.0f, bottom - r.y);
    }
    return r;
}
static bool UIContains(Vector2 p, Rectangle r) {
    if(!LandscapeUIAllowed())return false;
    r = UIClipped(r);
    return r.width > 0 && r.height > 0 && CheckCollisionPointRec(p, r);
}
static void UIBeginScissorMode(int x, int y, int w, int h) {
    Rectangle clip = UIClipped({(float)x, (float)y, (float)w, (float)h});
    g_uiClips.push_back(clip);
    BeginScissorMode((int)clip.x, (int)clip.y, (int)clip.width, (int)clip.height);
}
static void UIEndScissorMode() {
    if (!g_uiClips.empty()) g_uiClips.pop_back();
    if (g_uiClips.empty()) EndScissorMode();
    else { Rectangle r = g_uiClips.back(); BeginScissorMode((int)r.x, (int)r.y, (int)r.width, (int)r.height); }
}
static void UIRegister(Rectangle r) {
    r = UIClipped(r);
    if (r.width <= 0 || r.height <= 0) return;
    if (g_uiRects.size() < 256) g_uiRects.push_back(r);
    Vector2 pointer=GetMousePosition();
    if (LandscapeUIAllowed() && IsMouseButtonPressed(MOUSE_BUTTON_LEFT) && CheckCollisionPointRec(pointer, r)) g_uiGestureOwned = true;
}
static bool UIHit(Vector2 m) {
    if (g_uiGestureOwned || g_uiClickTaken) return true;
    if(!LandscapeUIAllowed())return false;
    if (g_uiShieldOn && CheckCollisionPointRec(m, g_uiShield)) return true;
    // A control protects its visible bounds. Extra world-only padding is small
    // enough that adjacent controls and open ground keep their intended meaning.
    const float pad = 3.0f;
    for (const auto* list : { &g_uiRectsPrev, &g_uiRects })
        for (const Rectangle& r : *list)
            if (m.x >= r.x - pad && m.x <= r.x + r.width + pad && m.y >= r.y - pad && m.y <= r.y + r.height + pad) return true;
    return false;
}
static void UIFrameReset() {
    g_uiRectsPrev.swap(g_uiRects); g_uiRects.clear(); g_uiClips.clear();
    g_uiClickTaken = false;
    if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) {
        g_uiGestureOwned = false;
        g_uiGestureOwned = UIHit(GetMousePosition());
    } else if (!IsMouseButtonDown(MOUSE_BUTTON_LEFT) && !IsMouseButtonReleased(MOUSE_BUTTON_LEFT)) g_uiGestureOwned = false;
}
static bool UIClick(Rectangle r, bool enabled = true) {
    UIRegister(r);
    if (!enabled || g_uiClickTaken || !IsMouseButtonPressed(MOUSE_BUTTON_LEFT) || !UIContains(GetMousePosition(), r)) return false;
    if (g_uiShieldOn && !g_uiShieldBypass && CheckCollisionPointRec(GetMousePosition(), g_uiShield)) return false;
    g_uiClickTaken = true; g_uiGestureOwned = true;
    return true;
}
static bool Button(Rectangle r, const std::string& label, bool enabled) {
    // A small (1.5px/side) outset on both the visual rect and the click/tap hit-test -
    // enough to feel a bit more generous without crowding neighboring buttons the way
    // a bigger outset plus a drop shadow did (both have been tried and back out).
    const float kOutset = 1.5f;
    Rectangle big = { r.x - kOutset, r.y - kOutset, r.width + kOutset * 2.0f, r.height + kOutset * 2.0f };
    Vector2 mouse = GetMousePosition();
    bool hover = CheckCollisionPointRec(mouse, big);
    // Readability pass (2026-09-27): solid dark leather with cream lettering - the old
    // see-through slate with dark text washed out over the 3D world.
    Color bg = !enabled ? Color{ 150, 144, 136, 200 } : (hover ? Color{ 92, 68, 46, 245 } : Color{ 62, 46, 34, 235 });
    DrawRectangleRounded(big, 0.25f, 6, bg);
    DrawRectangleRoundedLines(big, 0.25f, 6, enabled ? Color{ 176, 132, 72, 255 } : Fade(BLACK, 0.35f));
    int fs = 14, tw = MeasureUIText(label.c_str(), fs);
    while (tw > big.width - 8 && fs > 10) tw = MeasureUIText(label.c_str(), --fs); // long labels shrink to fit
    Color fg = enabled ? Color{ 248, 236, 210, 255 } : Color{ 70, 64, 58, 255 };
    int tx = (int)(big.x + (big.width - tw) / 2.0f), ty = (int)(big.y + (big.height - fs) / 2.0f);
    if (enabled) DrawUIText(label.c_str(), tx + 1, ty + 1, fs, Fade(BLACK, 0.55f));
    DrawUIText(label.c_str(), tx, ty, fs, fg);
    bool clicked = UIClick(big, enabled);
    if (clicked && g_uiShieldOn && !g_uiShieldBypass && CheckCollisionPointRec(mouse, g_uiShield)) clicked = false;
    if (clicked) PlaySfx(SfxId::Click); // central UI click - one place covers all buttons
    return clicked;
}

// ---- UO look kit (2026-09-26) -------------------------------------------------
// Shared by the corpse window, the backpack, the paperdoll and the spell bar:
// procedurally generated leather / parchment / dark-wood surfaces (tiling
// 256px textures, made once), bronze-framed "gump" panels with corner studs,
// and small hand-drawn icons for the stackables (coins, hides, reagents...).
static float UOHash01(float x, float y) { float h = sinf(x * 127.1f + y * 311.7f) * 43758.5453f; return h - floorf(h); }
enum UOSurface { kUoLeather = 0, kUoParchment, kUoDarkWood, kUoStone, kUoSurfaceCount };
static Texture2D g_uoTex[kUoSurfaceCount];
static bool g_uoTexReady = false;
static void UOEnsureTextures() {
    if (g_uoTexReady) return;
    g_uoTexReady = true;
    struct Pal { Color a, b; float grain; int seed; float scale; };
    const Pal pals[kUoSurfaceCount] = {
        { { 70, 44, 26, 255 }, { 128, 86, 50, 255 }, 18.0f, 11, 5.0f },   // leather (bag)
        { { 176, 150, 110, 255 }, { 226, 206, 166, 255 }, 10.0f, 23, 3.0f }, // parchment (paperdoll)
        { { 30, 24, 22, 255 }, { 70, 56, 46, 255 }, 12.0f, 37, 6.0f },     // dark wood (corpse, spell bar)
        { { 92, 90, 92, 255 }, { 150, 146, 140, 255 }, 14.0f, 51, 4.0f },  // stone (slots)
    };
    const int N = 256;
    for (int k = 0; k < kUoSurfaceCount; k++) {
        Image noise = GenImagePerlinNoise(N, N, pals[k].seed * 97, pals[k].seed * 31, pals[k].scale);
        Color* np = LoadImageColors(noise);
        Image img = GenImageColor(N, N, BLANK);
        Color* px = (Color*)img.data;
        for (int i = 0; i < N * N; i++) {
            float n = np[i].r / 255.0f;
            float g = (UOHash01((float)(i % N), (float)(i / N) + k * 7.0f) - 0.5f) * pals[k].grain;
            if (k == kUoDarkWood) n = 0.5f + 0.5f * sinf((i % N) * 0.05f + n * 6.0f) * 0.6f + (n - 0.5f) * 0.4f; // grain streaks
            Color c = ColorLerp(pals[k].a, pals[k].b, std::clamp(n, 0.0f, 1.0f));
            px[i] = { (unsigned char)std::clamp(c.r + g, 0.0f, 255.0f), (unsigned char)std::clamp(c.g + g, 0.0f, 255.0f),
                      (unsigned char)std::clamp(c.b + g, 0.0f, 255.0f), 255 };
        }
        UnloadImageColors(np);
        UnloadImage(noise);
        g_uoTex[k] = LoadTextureFromImage(img);
        UnloadImage(img);
        SetTextureWrap(g_uoTex[k], TEXTURE_WRAP_REPEAT);
        SetTextureFilter(g_uoTex[k], TEXTURE_FILTER_BILINEAR);
    }
}
static void UOFill(Rectangle r, int surface, Color tint = WHITE) {
    UOEnsureTextures();
    DrawTexturePro(g_uoTex[surface], { r.x * 0.7f, r.y * 0.7f, r.width, r.height }, r, { 0, 0 }, 0.0f, tint);
}
static const Color kUoBronze = { 150, 112, 58, 255 }, kUoBronzeHi = { 222, 184, 110, 255 }, kUoBronzeLo = { 70, 48, 24, 255 };
static const Color kUoGoldText = { 236, 208, 140, 255 };
// Restrained bronze frame: preserve parchment contrast and existing hit areas.
static void UODrawGump(Rectangle r, int surface, Color tint = WHITE) {
    if(g_landscapeActive && r.width>=350 && (r.height>=260 || (r.y>=230 && r.height>=90)))g_landscapeDialog=true;
    DrawRectangleRec({ r.x + 3, r.y + 6, r.width, r.height }, Fade(BLACK, 0.28f));
    UOFill(r, surface, tint);
    DrawRectangleLinesEx(r, 1.0f, Color{ 24, 20, 18, 255 });
    DrawRectangleLinesEx({ r.x + 1, r.y + 1, r.width - 2, r.height - 2 }, 1.0f, kUoBronze);
    DrawLineEx({ r.x + 2, r.y + 2 }, { r.x + r.width - 2, r.y + 2 }, 1.0f, Fade(kUoBronzeHi, 0.7f));
    DrawLineEx({ r.x + 2, r.y + r.height - 2 }, { r.x + r.width - 2, r.y + r.height - 2 }, 1.0f, kUoBronzeLo);
    // Small corner accents replace the oversized decorative studs.
    for (float cx : { r.x + 4, r.x + r.width - 4 }) {
        float dir = cx < r.x + r.width * 0.5f ? 1.0f : -1.0f;
        DrawLineEx({ cx, r.y + 4 }, { cx + dir * 10, r.y + 4 }, 1.0f, kUoBronzeHi);
        DrawLineEx({ cx, r.y + 4 }, { cx, r.y + 12 }, 1.0f, kUoBronzeHi);
    }
}
// Engraved title plate centered on a gump's top edge.
static void UODrawTitle(Rectangle gump, const std::string& text, int fsz = 14) {
    int w = MeasureUIText(text.c_str(), fsz);
    Rectangle t = { gump.x + gump.width / 2.0f - w / 2.0f - 16, gump.y - 10, (float)w + 32, (float)fsz + 12 };
    DrawRectangleRec(t, Color{ 40, 26, 16, 255 });
    DrawRectangleLinesEx(t, 2.0f, kUoBronze);
    DrawRectangleLinesEx({ t.x + 2, t.y + 2, t.width - 4, t.height - 4 }, 1.0f, kUoBronzeLo);
    DrawUIText(text.c_str(), (int)(t.x + 16), (int)(t.y + 6), fsz, kUoGoldText);
}
// Recessed square slot (paperdoll slots, bag cells).
static void UODrawSlot(Rectangle r, bool lit = false) {
    UOFill(r, kUoStone, Color{ 120, 116, 112, 255 });
    DrawRectangleGradientV((int)r.x, (int)r.y, (int)r.width, (int)(r.height * 0.45f), Fade(BLACK, 0.45f), Fade(BLACK, 0.0f));
    DrawRectangleLinesEx(r, 2.0f, lit ? kUoBronzeHi : kUoBronze);
    DrawLineEx({ r.x + 2, r.y + r.height - 2 }, { r.x + r.width - 2, r.y + r.height - 2 }, 1.0f, Fade(kUoBronzeHi, 0.6f));
    DrawLineEx({ r.x + 2, r.y + 2 }, { r.x + r.width - 2, r.y + 2 }, 1.0f, Fade(BLACK, 0.6f));
}
// Close "X" button in a gump's top-right corner.
static bool UOCloseButton(Rectangle gump) {
    Rectangle b = { gump.x + gump.width - 30, gump.y + 8, 22, 22 };
    Vector2 m = GetMousePosition();
    bool hover = CheckCollisionPointRec(m, b);
    DrawRectangleRec(b, hover ? Color{ 110, 40, 30, 255 } : Color{ 60, 30, 22, 255 });
    DrawRectangleLinesEx(b, 1.5f, kUoBronze);
    DrawLineEx({ b.x + 6, b.y + 6 }, { b.x + 16, b.y + 16 }, 2.5f, kUoGoldText);
    DrawLineEx({ b.x + 16, b.y + 6 }, { b.x + 6, b.y + 16 }, 2.5f, kUoGoldText);
    bool clicked = UIClick(b);
    if (clicked && g_uiShieldOn && !g_uiShieldBypass && CheckCollisionPointRec(m, g_uiShield)) clicked = false;
    if (clicked) PlaySfx(SfxId::Click);
    return clicked;
}
// Bronze-and-leather action button in the gump style.
static bool UOButton(Rectangle r, const std::string& label, bool enabled = true) {
    Vector2 m = GetMousePosition();
    bool hover = enabled && CheckCollisionPointRec(m, r);
    DrawRectangleRec(r, enabled ? (hover ? Color{ 96, 62, 34, 255 } : Color{ 70, 44, 24, 255 }) : Color{ 60, 56, 52, 255 });
    DrawRectangleGradientV((int)r.x, (int)r.y, (int)r.width, (int)(r.height / 2), Fade(WHITE, 0.10f), Fade(WHITE, 0.0f));
    DrawRectangleLinesEx(r, 2.0f, enabled ? kUoBronze : Color{ 100, 96, 90, 255 });
    int tw = MeasureUIText(label.c_str(), 14);
    DrawUIText(label.c_str(), (int)(r.x + (r.width - tw) / 2), (int)(r.y + (r.height - 14) / 2), 14,
               enabled ? kUoGoldText : Color{ 150, 146, 140, 255 });
    bool clicked = UIClick(r, enabled);
    if (clicked && g_uiShieldOn && !g_uiShieldBypass && CheckCollisionPointRec(m, g_uiShield)) clicked = false;
    if (clicked) PlaySfx(SfxId::Click);
    return clicked;
}
static bool UOTapped(Rectangle r) {
    Vector2 m = GetMousePosition();
    bool clicked = UIClick(r);
    if (clicked && g_uiShieldOn && !g_uiShieldBypass && CheckCollisionPointRec(m, g_uiShield)) clicked = false;
    return clicked;
}
// Stack count in the UO corner-number style.
static void UODrawCount(float x, float y, int n) {
    if (n <= 1) return;
    std::string t = std::to_string(n);
    int w = MeasureUIText(t.c_str(), 12);
    for (int dx = -1; dx <= 1; dx++)
        for (int dy = -1; dy <= 1; dy++) if (dx || dy) DrawUIText(t.c_str(), (int)x - w + dx, (int)y + dy, 12, BLACK);
    DrawUIText(t.c_str(), (int)x - w, (int)y, 12, Color{ 255, 244, 214, 255 });
}
// Hand-drawn icons for stackables, centered on (cx, cy), roughly `sz` across.
enum UOIcon { kUoiGold = 0, kUoiHides, kUoiFurs, kUoiReagents, kUoiBandages, kUoiLogs, kUoiOre, kUoiFish, kUoiIce, kUoiLeather };
static void UODrawIcon(int icon, float cx, float cy, float sz) {
    float u = sz / 40.0f;
    switch (icon) {
        case kUoiGold: {
            const Vector2 off[6] = { { -8, 6 }, { 6, 7 }, { -1, 1 }, { 9, -2 }, { -7, -4 }, { 1, -8 } };
            for (const Vector2& o : off) {
                Vector2 p = { cx + o.x * u, cy + o.y * u };
                DrawEllipse((int)p.x, (int)(p.y + 1.5f * u), 8.5f * u, 5.5f * u, Color{ 120, 84, 18, 255 });
                DrawEllipse((int)p.x, (int)p.y, 8.5f * u, 5.5f * u, Color{ 232, 186, 58, 255 });
                DrawEllipse((int)p.x - (int)u, (int)p.y - (int)u, 4.0f * u, 2.2f * u, Color{ 255, 232, 150, 255 });
            }
            break;
        }
        case kUoiHides: case kUoiFurs: case kUoiLeather: {
            Color c = icon == kUoiFurs ? Color{ 214, 206, 190, 255 } : (icon == kUoiLeather ? Color{ 128, 78, 40, 255 } : Color{ 160, 104, 58, 255 });
            Vector2 pts[9];
            for (int i = 0; i < 9; i++) {
                float a = i * 6.2832f / 9.0f;
                float r = (13.0f + ((i * 37) % 5) * 1.8f) * u;
                pts[i] = { cx + cosf(a) * r * 1.2f, cy + sinf(a) * r * 0.8f };
            }
            for (int i = 0; i < 9; i++) DrawTriangle({ cx, cy }, pts[(i + 1) % 9], pts[i], c);
            for (int i = 0; i < 9; i++) DrawLineEx(pts[i], pts[(i + 1) % 9], 1.5f, ColorBrightness(c, -0.4f));
            if (icon == kUoiLeather) { DrawLineEx({ cx - 10 * u, cy - 3 * u }, { cx + 10 * u, cy - 3 * u }, 2.0f, ColorBrightness(c, -0.3f)); }
            else for (int i = 0; i < 4; i++) DrawCircleV({ cx + (i - 1.5f) * 6 * u, cy + ((i % 2) ? 3 : -3) * u }, 1.8f * u, ColorBrightness(c, -0.25f));
            break;
        }
        case kUoiReagents: {
            DrawCircleV({ cx - 7 * u, cy + 3 * u }, 5.5f * u, Color{ 40, 36, 44, 255 });   // black pearl
            DrawCircleV({ cx - 8.5f * u, cy + 1.5f * u }, 1.8f * u, Color{ 170, 170, 190, 255 });
            DrawEllipse((int)(cx + 6 * u), (int)(cy + 4 * u), 6 * u, 5 * u, Color{ 236, 230, 212, 255 }); // garlic
            DrawTriangle({ cx + 6 * u, cy - 5 * u }, { cx + 3 * u, cy + 1 * u }, { cx + 9 * u, cy + 1 * u }, Color{ 236, 230, 212, 255 });
            DrawLineEx({ cx - 2 * u, cy - 10 * u }, { cx + 1 * u, cy + 6 * u }, 3.0f * u, Color{ 140, 96, 50, 255 }); // mandrake root
            DrawLineEx({ cx + 1 * u, cy + 6 * u }, { cx - 3 * u, cy + 11 * u }, 2.0f * u, Color{ 140, 96, 50, 255 });
            break;
        }
        case kUoiBandages: {
            DrawCircleV({ cx, cy }, 11 * u, Color{ 236, 232, 222, 255 });
            DrawCircleLines((int)cx, (int)cy, 11 * u, Color{ 170, 164, 150, 255 });
            DrawCircleLines((int)cx, (int)cy, 7 * u, Color{ 190, 184, 170, 255 });
            DrawCircleV({ cx, cy }, 3 * u, Color{ 200, 194, 180, 255 });
            DrawRectangleRec({ cx + 6 * u, cy + 4 * u, 12 * u, 5 * u }, Color{ 236, 232, 222, 255 });
            break;
        }
        case kUoiLogs: {
            for (int i = 0; i < 3; i++) {
                float y = cy + (i - 1) * 7 * u + (i == 1 ? -3 * u : 0);
                float x = cx + (i == 1 ? 0 : (i == 0 ? -5 : 5)) * u;
                DrawRectangleRec({ x - 14 * u, y - 3.5f * u, 26 * u, 7 * u }, Color{ 118, 78, 44, 255 });
                DrawCircleV({ x + 12 * u, y }, 3.6f * u, Color{ 210, 170, 110, 255 });
                DrawCircleLines((int)(x + 12 * u), (int)y, 2.0f * u, Color{ 150, 110, 60, 255 });
            }
            break;
        }
        case kUoiOre: {
            for (int i = 0; i < 2; i++) {
                float y = cy + (i ? 5 : -3) * u, x = cx + (i ? 3 : -3) * u;
                Vector2 a = { x - 11 * u, y + 5 * u }, b = { x + 11 * u, y + 5 * u }, c = { x + 7 * u, y - 5 * u }, d = { x - 7 * u, y - 5 * u };
                DrawTriangle(a, b, c, Color{ 150, 152, 160, 255 }); DrawTriangle(a, c, d, Color{ 150, 152, 160, 255 });
                DrawTriangle(d, c, { x + 5 * u, y - 7 * u }, Color{ 200, 202, 210, 255 });
                DrawTriangle(d, { x + 5 * u, y - 7 * u }, { x - 5 * u, y - 7 * u }, Color{ 200, 202, 210, 255 });
            }
            break;
        }
        case kUoiFish: {
            DrawEllipse((int)cx - (int)(2 * u), (int)cy, 12 * u, 6 * u, Color{ 110, 140, 160, 255 });
            DrawTriangle({ cx + 9 * u, cy }, { cx + 17 * u, cy + 7 * u }, { cx + 17 * u, cy - 7 * u }, Color{ 90, 120, 140, 255 });
            DrawCircleV({ cx - 9 * u, cy - 1.5f * u }, 1.5f * u, BLACK);
            break;
        }
        case kUoiIce: {
            DrawTriangle({ cx, cy - 13 * u }, { cx - 7 * u, cy + 9 * u }, { cx + 7 * u, cy + 9 * u }, Color{ 190, 230, 250, 255 });
            DrawTriangle({ cx - 8 * u, cy - 4 * u }, { cx - 13 * u, cy + 9 * u }, { cx - 3 * u, cy + 9 * u }, Color{ 160, 210, 240, 255 });
            DrawTriangle({ cx + 8 * u, cy - 6 * u }, { cx + 3 * u, cy + 9 * u }, { cx + 13 * u, cy + 9 * u }, Color{ 170, 220, 245, 255 });
            break;
        }
    }
}
// Deterministic scattered placement (UO containers strew their contents):
// entry i of n on a jittered grid inside `area`, seeded so it doesn't dance.
static Vector2 UOScatter(Rectangle area, int i, float cell, int seed) {
    int cols = std::max(1, (int)(area.width / cell));
    int col = i % cols, row = i / cols;
    float jx = (UOHash01((float)(i * 13 + seed), 1.7f) - 0.5f) * cell * 0.28f;
    float jy = (UOHash01((float)(i * 7 + seed), 5.3f) - 0.5f) * cell * 0.22f;
    float padX = (area.width - cols * cell) * 0.5f;
    return { area.x + padX + (col + 0.5f) * cell + jx, area.y + (row + 0.5f) * cell + jy };
}

// Tap-to-interact button - the touch equivalent of the [E] key, shown only while in
// range of something interactable (mirrors the virtual joystick's bottom-left corner
// on the opposite side of the screen). Called after the world/scissor for the same
// reason as DrawVirtualJoystick - so it isn't painted over and isn't affected by the
// scissor region.
static bool DrawInteractButton(const std::string& label) {
    // (2026-09-27) gold, pulsing, and wide enough for "Fight Timber Wolf"
    Rectangle r = { kViewport.x + kViewport.width - 186.0f, kViewport.y + kViewport.height - 92.0f, 170.0f, 64.0f };
    UIRegister(r);
    Vector2 m = GetMousePosition();
    bool hover = CheckCollisionPointRec(m, r);
    float p = 0.5f + 0.5f * sinf((float)GetTime() * 4.0f);
    DrawRectangleRounded({ r.x - 3, r.y - 3, r.width + 6, r.height + 6 }, 0.3f, 8, Fade(Color{ 255, 214, 110, 255 }, 0.25f + 0.25f * p));
    DrawRectangleRounded(r, 0.3f, 8, hover ? Color{ 236, 190, 90, 255 } : Color{ 214, 164, 70, 255 });
    DrawRectangleRoundedLines(r, 0.3f, 8, Color{ 90, 60, 24, 255 });
    std::string t = label.rfind("[E] ", 0) == 0 ? label.substr(4) : label;
    int fs = 17, tw = MeasureUIText(t.c_str(), fs);
    while (tw > r.width - 14 && fs > 11) tw = MeasureUIText(t.c_str(), --fs);
    DrawUIText(t.c_str(), (int)(r.x + (r.width - tw) / 2), (int)(r.y + r.height / 2 - fs / 2 - 6), fs, Color{ 40, 24, 10, 255 });
    const char* hint = "tap or press E";
    DrawUIText(hint, (int)(r.x + (r.width - MeasureUIText(hint, 10)) / 2), (int)(r.y + r.height - 16), 10, Color{ 80, 50, 20, 255 });
    bool clicked = UIClick(r);
    if (clicked && g_uiShieldOn && !g_uiShieldBypass && CheckCollisionPointRec(m, g_uiShield)) clicked = false;
    if (clicked) PlaySfx(SfxId::Click);
    return clicked;
}
// The "[E] ..." prompt over the world: bigger, darker backing, above the belt and spell bar.
static void DrawPromptLabel(const std::string& prompt, int screenW, int screenH) {
    if(g_landscapeActive && g_landscapeWorld && !g_landscapeDialog) {
        g_landscapeCaptions.push_back({prompt,16,Color{255,226,150,255},true});return;
    }
    int fs = 16, w = MeasureUIText(prompt.c_str(), fs);
    int sx = (screenW - w) / 2, sy = screenH - 176;
    DrawRectangleRounded({ (float)sx - 10, (float)sy - 5, (float)w + 20, (float)fs + 12 }, 0.4f, 6, Fade(Color{ 20, 14, 10, 255 }, 0.82f));
    DrawRectangleRoundedLines({ (float)sx - 10, (float)sy - 5, (float)w + 20, (float)fs + 12 }, 0.4f, 6, Color{ 214, 164, 70, 255 });
    DrawUIText(prompt.c_str(), sx, sy, fs, Color{ 255, 226, 150, 255 });
}
// A HUD line over the 3D world: dark pill, light text.
static void DrawHudLine(const char* text, int x, int y, int fs = 13, Color c = Color{ 240, 230, 206, 255 }) {
    if(g_landscapeActive && g_landscapeWorld && !g_landscapeDialog && y==196) {
        g_landscapeCaptions.push_back({"Drag to turn. Pinch or wheel to zoom.",12,c,false});return;
    }
    if(g_landscapeActive && g_landscapeWorld && !g_landscapeDialog && y>=600) {
        g_landscapeCaptions.push_back({"Tap ground to walk. Approach a door to enter.",12,c,false});return;
    }
    int tw = MeasureUIText(text, fs);
    DrawRectangleRounded({ (float)x - 7, (float)y - 3, (float)tw + 14, (float)fs + 8 }, 0.35f, 6, Fade(Color{ 20, 14, 10, 255 }, 0.72f));
    DrawUIText(text, x, y, fs, c);
}

// Touch-drag scrolling (2026-09-22) - every scrollable list in the game (Craft/
// Provisioner recipe & backpack lists, Magic's spell list, Pets, Bank, House, Skills,
// the Character screen's backpack) only ever responded to a desktop mouse wheel; mobile
// has no wheel at all, so on a touch device none of them could be scrolled past the
// first screenful. raylib's Emscripten GLFW3 layer already maps a single touch to the
// left mouse button (the same convention the virtual joystick and tap-to-interact
// button already rely on elsewhere in this file), so drag-to-scroll uses the same
// IsMouseButtonDown/GetMousePosition APIs - no separate touch API needed. One shared
// pair of drag-tracking statics is enough since only one list can be actively dragged
// at a time (one input device, one screen visible at once) regardless of which list.
// Drop-in replacement for the old `GetMouseWheelMove() * 24.0f` expression at every
// call site: `scroll -= ScrollDelta(area);` replaces the old
// `if (CheckCollisionPointRec(...)) scroll -= GetMouseWheelMove() * 24.0f;` entirely
// (the area-hover check now lives inside this function), desktop wheel scrolling is
// completely unchanged.
static bool g_scrollDragging = false;
static float g_scrollDragLastY = 0.0f;
static float ScrollDelta(Rectangle area) {
    Vector2 mouse = GetMousePosition();
    bool overArea = CheckCollisionPointRec(mouse, area);
    float delta = overArea ? GetMouseWheelMove() * 24.0f : 0.0f;
    if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT) && overArea) {
        g_scrollDragging = true;
        g_scrollDragLastY = mouse.y;
    } else if (IsMouseButtonDown(MOUSE_BUTTON_LEFT) && g_scrollDragging) {
        // Finger moves up (mouse.y decreases) -> reveal content below -> scroll
        // increases; matches the `scroll -= ScrollDelta(...)` sign convention every
        // call site already uses for the wheel term.
        delta += (mouse.y - g_scrollDragLastY);
        g_scrollDragLastY = mouse.y;
    } else {
        g_scrollDragging = false;
    }
    return delta;
}

// ---------------------------------------------------------------------
// Live-combat spell hotbar (2026-09-22) - shared by DrawWildernessScreen and
// DrawHuntScreen (dungeons), the two live-combat screens. Assignment only touches
// s.combatHotbar/s.hotbarPickerSlot, no screen-specific monster state, so it's a real
// shared abstraction rather than the deliberate per-screen duplication used for the
// combat math itself (see ActiveMonster vs ActiveDungeonMonster's own comments).
// ---------------------------------------------------------------------

// Draws the 5 hotbar slots at the fixed spot the old "first 3 known offensive spells"
// strip used to occupy (between the joystick and the interact button) and returns
// which slot was just tapped, or -1. The caller decides what a tap means: outside
// combat it opens the assignment picker, in combat it casts - see the call sites in
// DrawWildernessScreen/DrawHuntScreen.
//
// Denied taps (2026-09-25): in combat, taps on slots that can't currently fire
// (cooldown/cast-lock, unaffordable) are ALSO reported - Button with enabled=false
// would swallow them silently, which felt like "I can only cast once". The caller
// flashes the slot (hotbarDenyT) and explains via floater, so every tap answers.
// Empty slots stay silent: "+" already says there's nothing there.
static const float kHotbarDenyTime = 0.45f;
static Rectangle CombatHotbarSlotRect(int i,float x,float y) {
    return {x+(i%4)*84.0f,y+(i/4)*98.0f,72.0f,72.0f};
}
static int DrawCombatHotbarRow(const GameState& s, bool inCombat, const float* spellCds, float castLockT,
                               float x = 190.0f, float y = kViewport.y + kViewport.height - 200.0f) {
    // Spell bar look (2026-09-26): a bronze-framed dark-wood bar of recessed
    // slots showing each spell's icon, its key number and mana cost, a radial
    // cooldown sweep with the seconds left, a gold rim when it's ready to fire,
    // and a cold blue cast when you can't afford it. Tap/keys behave as before.
    int tapped = -1;
    Vector2 mouse = GetMousePosition();
    const int n = (int)s.combatHotbar.size();
    const float slotW = 72.0f;
    const int cols=std::min(n,4), rows=(n+3)/4;
    Rectangle bar={x-9,y-8,cols*84.0f+6,rows*98.0f-2};
    UIRegister(bar);
    UODrawGump(bar, kUoDarkWood);
    float t = (float)GetTime();
    for (int i = 0; i < n; i++) {
        Rectangle r=CombatHotbarSlotRect(i,x,y);
        Rectangle big = { r.x - 3.0f, r.y - 3.0f, r.width + 6.0f, r.height + 6.0f };
        int spellIdx = s.combatHotbar[i];
        bool has = spellIdx >= 0 && spellIdx < (int)kSpells.size();
        bool enabled = true, affordable = true, ready = true;
        float cdFrac = 0.0f, cdLeft = 0.0f;
        if (has) {
            const Spell& sp = kSpells[spellIdx];
            if (inCombat) {
                affordable = s.mana >= sp.manaCost && s.reagents >= LiveReagentCost(spellIdx);
                if (spellCds != nullptr) {
                    cdLeft = std::max(spellCds[spellIdx], castLockT);
                    cdFrac = std::max(spellCds[spellIdx] / kSpellCooldown, castLockT / kCastLockTime);
                }
                ready = spellCds != nullptr && castLockT <= 0.0f && spellCds[spellIdx] <= 0.0f;
                enabled = affordable && ready;
            }
        } else if (inCombat) {
            enabled = false;
        }
        bool hover = UIContains(mouse, r);
        bool shielded = g_uiShieldOn && !g_uiShieldBypass && CheckCollisionPointRec(mouse, g_uiShield);
        bool down = hover && IsMouseButtonDown(MOUSE_BUTTON_LEFT) && !shielded;
        // slot + icon
        UODrawSlot(r, has && enabled && inCombat);
        if (has) {
            const Spell& sp = kSpells[spellIdx];
            const Texture2D* icon = nullptr;
            if (sp.necro) icon = NecroIcon(spellIdx);
            else if (sp.chiv) icon = ChivIcon(spellIdx);
            else if (spellIdx < 16 && g_assets.spellIconPerSpellOk[spellIdx]) icon = &g_assets.spellIconPerSpell[spellIdx];
            else if (sp.type == SpellType::Utility && g_assets.spellIconUtilityOk) icon = &g_assets.spellIconUtility;
            else if (g_assets.spellIconOffensiveOk) icon = &g_assets.spellIconOffensive;
            float inset = down ? 5.0f : 4.0f;
            Rectangle ir = { r.x + inset, r.y + inset, r.width - inset * 2, r.height - inset * 2 };
            Color tint = !affordable ? Color{ 110, 124, 170, 255 } : WHITE;
            if (icon) DrawTexturePro(*icon, { 0, 0, (float)icon->width, (float)icon->height }, ir, { 0, 0 }, 0.0f, tint);
            else DrawUIText(sp.name.substr(0, 2).c_str(), (int)ir.x + 14, (int)ir.y + 16, 18, kUoGoldText);
            // cooldown sweep: the unready part of the dial darkened, clockwise from 12
            if (cdFrac > 0.001f) {
                UIBeginScissorMode((int)ir.x, (int)ir.y, (int)ir.width, (int)ir.height);
                DrawCircleSector({ ir.x + ir.width / 2, ir.y + ir.height / 2 }, ir.width, -90.0f + 360.0f * (1.0f - cdFrac), 270.0f, 32,
                                 Fade(BLACK, 0.62f));
                UIEndScissorMode();
                if (cdLeft > 0.25f) {
                    std::string cs = TextFormat("%.1f", cdLeft);
                    int cw = MeasureUIText(cs.c_str(), 16);
                    DrawUIText(cs.c_str(), (int)(ir.x + ir.width / 2 - cw / 2) + 1, (int)(ir.y + ir.height / 2 - 8) + 1, 16, BLACK);
                    DrawUIText(cs.c_str(), (int)(ir.x + ir.width / 2 - cw / 2), (int)(ir.y + ir.height / 2 - 8), 16, WHITE);
                }
            }
            // ready: a soft gold rim that breathes
            if (inCombat && enabled) {
                float p = 0.5f + 0.5f * sinf(t * 3.0f + i);
                DrawRectangleLinesEx(big, 2.0f, Fade(Color{ 255, 214, 110, 255 }, 0.35f + 0.35f * p));
            }
            // mana cost pill, bottom-right
            std::string mc = std::to_string(sp.manaCost);
            int mw = MeasureUIText(mc.c_str(), 10);
            Rectangle pill = { r.x + r.width - mw - 9.0f, r.y + r.height - 14.0f, (float)mw + 8.0f, 13.0f };
            DrawRectangleRounded(pill, 0.5f, 4, affordable ? Color{ 34, 60, 120, 230 } : Color{ 120, 30, 30, 230 });
            DrawUIText(mc.c_str(), (int)pill.x + 4, (int)pill.y + 1, 10, Color{ 200, 220, 255, 255 });
            // name under the slot
            size_t maxNm = slotW > 50.0f ? 10 : 7;
            std::string nm = sp.name.size() > maxNm ? sp.name.substr(0, maxNm - 1) + "." : sp.name;
            int nw = MeasureUIText(nm.c_str(), 10);
            DrawUIText(nm.c_str(), (int)(r.x + r.width / 2 - nw / 2), (int)(r.y + r.height + 5), 10, Color{ 220, 205, 170, 255 });
        } else {
            DrawUIText("+", (int)(r.x + r.width / 2 - 6), (int)(r.y + r.height / 2 - 14), 26, Fade(kUoBronzeHi, inCombat ? 0.3f : 0.7f));
        }
        // key number badge, top-left
        DrawCircleV({ r.x + 4, r.y + 4 }, 8.0f, Color{ 40, 26, 16, 255 });
        DrawCircleLines((int)r.x + 4, (int)r.y + 4, 8.0f, kUoBronze);
        DrawUIText(TextFormat("%d", i + 1), (int)r.x + 1, (int)r.y - 3, 11, kUoGoldText);
        if (hover && !down) DrawRectangleLinesEx(r, 1.0f, Fade(WHITE, 0.35f));
        // taps: enabled slots, and (in combat) denied slots too so the caller can explain
        bool press = UIClick(r, enabled || inCombat);
        if (press && (enabled || inCombat)) {
            tapped = i;
            PlaySfx(SfxId::Click);
        }
        if (inCombat && i < 5 && s.hotbarDenyT[i] > 0.0f) {
            float f = std::clamp(s.hotbarDenyT[i] / kHotbarDenyTime, 0.0f, 1.0f);
            DrawRectangleRec(big, Fade(Color{ 200, 40, 40, 255 }, 0.5f * f));
        }
    }
    { // reagent count over the bar's right end (2026-09-27) - red when you're about to run dry
        bool mage = false;
        for (int sp : s.combatHotbar) if (sp >= 0 && sp < (int)kSpells.size() && !kSpells[sp].necro && !kSpells[sp].chiv) mage = true;
        if (mage) {
            bool low = s.reagents < 5;
            std::string rt = s.reagents <= 0 ? "OUT of reagents" : TextFormat("Reagents %d", s.reagents);
            int fs = 13, tw = MeasureUIText(rt.c_str(), fs);
            Rectangle pr = { bar.x + bar.width - tw - 22.0f, bar.y - 24.0f, (float)tw + 16.0f, 21.0f };
            float pulse = low ? 0.6f + 0.4f * sinf(t * 6.0f) : 1.0f;
            DrawRectangleRounded(pr, 0.4f, 6, low ? Fade(Color{ 150, 26, 26, 255 }, 0.9f * pulse) : Fade(Color{ 30, 22, 16, 255 }, 0.85f));
            DrawRectangleRoundedLines(pr, 0.4f, 6, kUoBronze);
            DrawUIText(rt.c_str(), (int)pr.x + 8, (int)pr.y + 4, fs, low ? WHITE : Color{ 200, 230, 170, 255 });
        }
    }
    return tapped;
}

