// ---- Toasts (2026-09-27) ----
struct Toast { std::string text; float t = 0.0f, dur = 4.5f; Color col{}; };
static std::vector<Toast> g_toasts;
static std::string g_toastLast;
static Color ToastColor(const std::string& t) {
    auto has = [&](const char* k) { return t.find(k) != std::string::npos; };
    if (t.rfind("Not ", 0) == 0 || t.rfind("No ", 0) == 0 || has("can't") || has("isn't") || has("fizzle") || has("full") ||
        has("Out of") || has("Need ") || has("needs ") || has("defeated") || has("overran") || has("hunting you") || has("RAID"))
        return Color{ 255, 150, 110, 255 }; // warning
    if (has("+") || has("Collected") || has("slain") || has("Defeated") || has("finished") || has("threw back") || has("Bought") ||
        has("increases") || has("Victory") || has("VICTORY"))
        return Color{ 170, 235, 140, 255 }; // good news
    return Color{ 246, 236, 212, 255 };
}
// Blow-by-blow combat lines stay in the journal; toasts are for news.
static bool ToastIsChatter(const std::string& t) {
    auto has = [&](const char* k) { return t.find(k) != std::string::npos; };
    if (t.rfind("Your attack", 0) == 0 || t.rfind("You hit ", 0) == 0 || t.rfind("You cast ", 0) == 0) return true;
    if (has(" misses") || (has(" for ") && has(" damage") && !has("Out of")) || has(": \"")) return true;
    for (size_t i = 0; i + 3 < t.size(); i++) // skill ticks: "Tactics +0.2"
        if (t[i] == '+' && isdigit((unsigned char)t[i + 1]) && t[i + 2] == '.' && !has("increases")) return true;
    return false;
}
static void UpdateDrawToasts(GameState& s, int screenW, int screenH, bool play) {
    float dt = GetFrameTime();
    if (!g_bankPayNote.empty()) { s.logLine += " " + g_bankPayNote; g_bankPayNote.clear(); }
    if (s.logLine != g_toastLast) {
        g_toastLast = s.logLine;
        bool boring = s.logLine.empty() || s.logLine == "Welcome to Town Forge." || ToastIsChatter(s.logLine);
        if (!boring) {
            // a line that ticks (a countdown) updates its toast instead of stacking new ones
            if (!g_toasts.empty() && g_toasts.back().t < 0.35f) { g_toasts.back().text = s.logLine; g_toasts.back().col = ToastColor(s.logLine); }
            else {
                Toast t; t.text = s.logLine; t.col = ToastColor(s.logLine);
                t.dur = 4.0f + std::min(3.0f, s.logLine.size() / 40.0f) + (t.col.r == 255 ? 1.0f : 0.0f);
                g_toasts.push_back(t);
                while (g_toasts.size() > 3) g_toasts.erase(g_toasts.begin());
            }
        }
    }
    const int fs = 15;
    const bool nativeLandscape=play && g_landscapeWorld && !g_landscapeDialog;
    const float maxW = nativeLandscape ? 396.0f:(float)screenW - 60.0f;
    float y = play ? (float)screenH - 206.0f : (float)screenH - 44.0f; // bottom of the newest toast
    for (int i = (int)g_toasts.size() - 1; i >= 0; i--) {
        Toast& t = g_toasts[(size_t)i];
        t.t += dt;
        float a = std::min(1.0f, t.t / 0.15f) * std::clamp((t.dur - t.t) / 0.6f, 0.0f, 1.0f);
        if (a <= 0.0f) continue;
        // wrap to at most two lines
        std::vector<std::string> lines; std::string cur, word;
        std::istringstream ws(t.text);
        while (ws >> word) {
            std::string trial = cur.empty() ? word : cur + " " + word;
            if (MeasureUIText(trial.c_str(), fs) > maxW - 24 && !cur.empty()) { lines.push_back(cur); cur = word; }
            else cur = trial;
        }
        if (!cur.empty()) lines.push_back(cur);
        if (lines.size() > 2) {
            lines.resize(2);
            while(!lines[1].empty() && MeasureUIText((lines[1]+"...").c_str(),fs)>maxW-24)lines[1].pop_back();
            lines[1] += "...";
        }
        if(nativeLandscape){g_landscapeNotices.push_back({lines,t.col,a});continue;}
        float w = 0; for (auto& l : lines) w = std::max(w, (float)MeasureUIText(l.c_str(), fs));
        float h = lines.size() * (fs + 4.0f) + 12.0f;
        Rectangle r = { (screenW - w) / 2.0f - 14.0f, y - h, w + 28.0f, h };
        DrawRectangleRounded(r, 0.3f, 8, Fade(Color{ 18, 12, 8, 255 }, 0.86f * a));
        DrawRectangleRoundedLines(r, 0.3f, 8, Fade(t.col, 0.8f * a));
        for (size_t k = 0; k < lines.size(); k++) {
            int lw = MeasureUIText(lines[k].c_str(), fs);
            DrawUIText(lines[k].c_str(), (int)((screenW - lw) / 2), (int)(r.y + 7 + k * (fs + 4)), fs, Fade(t.col, a));
        }
        y = r.y - 6.0f;
    }
    g_toasts.erase(std::remove_if(g_toasts.begin(), g_toasts.end(), [](const Toast& t) { return t.t > t.dur; }), g_toasts.end());
}

// Hoisted out of main() so UpdateDrawFrame() (a plain function pointer, called every
// frame either by the desktop while-loop below or by emscripten_set_main_loop on web -
// see main()) can reach them; there's exactly one of each for the process's lifetime
// either way, so file-scope statics cost nothing bar naming a global.
static GameState g_state;
static const int kScreenW = 540;
static const int kScreenH = 900;
static float g_autosaveTimer = 0.0f;

// Desktop-only "zoom the whole view" - Mark asked for the game to look ~10-15% bigger.
// Every draw call in this file is an absolute pixel coordinate tuned for the fixed
// 540x900 internal resolution, so scaling *that* directly would mean re-tuning hundreds
// of Rectangle/font-size constants. Instead: keep every existing draw call completely
// untouched, rendering into a RenderTexture2D still sized 540x900, then present that
// texture scaled up to fill a proportionally bigger actual window - see UpdateDrawFrame
// and main(). SetMouseScale compensates so GetMousePosition()/Button() hit-tests keep
// seeing the original 540x900 coordinate space, unaware anything changed.
// **Not applied to the web build** - the canvas there is already independently scaled
// to fit the browser viewport by shell.html's CSS (unrelated to this constant), and
// raylib's Emscripten layer has its own canvas-buffer-to-CSS-size mouse mapping; adding
// SetMouseScale on top of that risked double-compensating and breaking tap targets in a
// way that's hard to verify without a real device. Web's equivalent zoom is a separate
// CSS change in shell.html instead (see its comment).
static const float kZoom = 1.125f;

// One frame's worth of update+draw. Split out of main() so it can be handed to
// emscripten_set_main_loop on web - a blocking `while(!WindowShouldClose())` loop only
// "works" there via -s ASYNCIFY around WindowShouldClose()'s internal emscripten_sleep(),
// which turned out to be fragile (it hung indefinitely partway through startup once this
// build grew past some threshold) - emscripten_set_main_loop is the robust, standard
// pattern raylib's own web examples use instead, with the browser's requestAnimationFrame
// driving each call rather than a C++-side blocking sleep.
static bool LandscapeDialogOpen(const GameState& s) {
    return IsMenuScreen(s.screen) || s.exploreMenuOpen || s.dungeonMenuOpen ||
        s.worldMapOpen || s.guideOpen || s.selectedTile.has_value() ||
        s.greetedNPC.has_value() || s.interiorGreeted || s.journalOpen ||
        s.recallPickerOpen || s.hotbarPickerSlot.has_value() || s.houseDesignerOpen ||
        s.houseChestOpen || s.houseCraftModule>=0 || s.openCorpseId>=0 ||
        g_trackOpen || (s.screen==Screen::Blackwake && g_denPanel!=0);
}
static void WarmWildernessCache(const GameState& s) {
    // Spread independent cache preparation over quiet town frames. The complete
    // town image remains displayed while each one-time task finishes.
    static int step=0;static double quietSince=0;
    if(step>=4)return;
    bool busy=s.screen!=Screen::Town || LandscapeDialogOpen(s) ||
        IsMouseButtonDown(MOUSE_BUTTON_LEFT) || IsKeyDown(KEY_W) || IsKeyDown(KEY_A) ||
        IsKeyDown(KEY_S) || IsKeyDown(KEY_D) || IsKeyDown(KEY_UP) || IsKeyDown(KEY_DOWN) ||
        IsKeyDown(KEY_LEFT) || IsKeyDown(KEY_RIGHT) || g_walkOn;
    if(busy){quietSince=GetTime();return;}
    if(GetTime()-quietSince<1.5)return;
    switch(step++) {
        case 0:Wild3DLoadModels();break;
        case 1:Wild3DEnsureGround();break;
        case 2:Wild3DBuildScatter();break;
        case 3:WildMapEnsureTexture();break;
    }
}
static void UpdateDrawFrame() {
    UIFrameReset(); // (2026-09-28) buttons drawn last frame guard this frame's world taps
#ifdef __EMSCRIPTEN__
    // Hold off on everything else until the async IndexedDB load (kicked off by
    // JS_InitPersistence in main()) has actually landed - reading the save file before
    // then would see an empty directory and silently start a fresh game even when a
    // real save exists on this device. Desktop has no equivalent wait (LoadGame already
    // ran synchronously in main(), before the loop even started, since its filesystem
    // is real and synchronous). Runs once; `loaded` latches true and this whole block
    // is skipped on every frame after.
    static bool loaded = false;
    if (!loaded) {
        if (!JS_PersistReady()) {
            BeginDrawing();
            ClearBackground(kColorPageBg);
            DrawUIText("Loading save data...", kScreenW / 2 - 90, kScreenH / 2, 18, kColorText);
            EndDrawing();
            return;
        }
        loaded = true;
        bool hadSave = LoadGame(g_state);
        if (hadSave && !g_state.logLine.empty() && g_state.logLine == "Welcome to Town Forge.")
            g_state.logLine = "Welcome back.";
        if (hadSave) SettleCatchUp(g_state); // the settlement kept working (2026-09-27)
        if (hadSave && !g_state.characterName.empty() && g_state.screen == Screen::Character)
            g_state.screen = Screen::Town; // returning adventurers open straight into the (3D) town
    }
#endif
    GameState& state = g_state;
    int screenW = kScreenW, screenH = kScreenH;
    float& autosaveTimer = g_autosaveTimer;
    float& resetArmedTimer = g_resetArmedTimer;
    // Inventory cannot be spent elsewhere while a guild transaction is in flight.
    if(JS_GuildCityPending()) {
        GuildNetPoll(); GuildHallTick(state);
        BeginDrawing(); ClearBackground(kColorPageBg);
        DrawUIText("Finishing guild transaction...",30,180,18,kColorHeading);
        DrawUIText("Your materials are reserved until the receipt is saved.",30,214,12,kColorText);
        if(!g_gnet.msg.empty()) DrawUIText(g_gnet.msg.c_str(),30,246,12,Color{150,40,30,255});
        if(UOButton({30,290,240,36},"Retry pending transaction",!g_gnet.busy)) JS_GuildCityAction("retry","");
        EndDrawing(); return;
    }
    {
        CombatFeelTick(); // hit-stop / shake timers, before anything reads GameDt()
        float dt = GameDt();

        // --- Update ---
        UpdateGathering(state, dt);
        UpdateUpgrade(state, dt);
        RegenMana(state, dt);
        MountTick(state); // (2026-09-28, #74)
        { // the audio pass (2026-09-28): music for where you are, footsteps underfoot
            Screen sc = state.screen, where = IsPlayScreen(sc) ? sc : g_playScreen;
            int want = (where == Screen::Town || where == Screen::Interior) ? 0 : where == Screen::Wilderness ? 1
                     : (where == Screen::Hunt && state.selectedDungeon.has_value()) ? 2 : -1;
            MusicTick(want, GetFrameTime());
            if (!state.playerIsGhost && state.playerDeathAnimT <= 0.0f) {
                if (sc == Screen::Town) FootstepTick(state.townPlayerPos, SfxId::StepStone);
                else if (sc == Screen::Interior) FootstepTick(state.interiorPlayerPos, SfxId::StepWood);
                else if (sc == Screen::Wilderness)
                    FootstepTick(state.wildernessPlayerPos, RegionAt(state.wildernessPlayerPos) == RegionId::Frostwastes ? SfxId::StepSnow : SfxId::StepGrass);
                else if (sc == Screen::Hunt && state.selectedDungeon.has_value()) FootstepTick(state.dungeonPlayerPos, SfxId::StepStone);
            }
        }
        RegenAllPetMana(state, dt);
        UpdateTameAttempt(state, dt);
        RegenNotoriety(state, dt);
        state.worldTime += dt;
        if (state.disengageGraceT > 0.0f) state.disengageGraceT -= dt; // manual-disengage grace (2026-09-25)
        if (state.wildAlertT >= 0.0f && (state.wildAlertT += dt) > 1.6f) state.wildAlertT = -1.0f; // "!" pop (2026-09-27)
        if (IsPlayScreen(state.screen)) g_playScreen = state.screen; // remembered for "Play" (2026-09-27)
        for (float& cd : state.commissionCd) if (cd > 0.0f) cd -= dt; // commission offers (2026-09-27)
        SettleTick(state, dt); // the settlement works in real time (2026-09-27)
        { // (2026-09-29) walking into a town from the wilds or a dungeon restores you (and your pets)
            static Screen prevPlay = Screen::Town;
            if (g_playScreen == Screen::Town && (prevPlay == Screen::Wilderness || prevPlay == Screen::Hunt) && !state.playerIsGhost) {
                bool worn = state.hp < state.maxHp || state.mana < MaxMana(state) - 0.5f;
                state.hp = state.maxHp; state.mana = MaxMana(state); state.poisonT = 0.0f; state.poisonLvl = 0;
                for (auto& p : state.pets) if (p.hp > 0.0f) { p.hp = p.maxHp; p.mana = p.maxMana; }
                if (worn) { state.logLine = "Safe inside the walls, you rest - health and mana restored."; Journal(state, state.logLine); }
            }
            prevPlay = g_playScreen;
        }
        { // auto-restock reagents on walking into a town (2026-09-27)
            static Screen prevScr = Screen::Town;
            if (state.screen == Screen::Town && prevScr != Screen::Town && state.autoReagents && state.reagents < 30) {
                int want = std::min(30 - state.reagents, state.gold);
                if (want > 0) {
                    state.gold -= want; state.reagents += want;
                    state.logLine = "The Provisioner's runner restocks you: +" + std::to_string(want) + " reagents (" + std::to_string(want) + "g).";
                    Journal(state, state.logLine);
                } else state.logLine = "Auto-restock: not enough gold for reagents.";
            }
            prevScr = state.screen;
        }
        WyrmTick(state, dt);   // the world boss's wake timer and heads (2026-09-27)
        BreakoutTick(state, dt); // a dungeon boss loose in the wilds, now and then (2026-09-29)
        TrackTick(state, dt);    // Tracking's pointer (2026-09-29)
        { // (2026-09-29) UO-style timers: poison ticks, the bandage being applied, the heal-potion timer
            PlayerPoisonTick(state, dt);
            g_healPotCd = std::max(0.0f, g_healPotCd - dt);
            if (state.bandageT >= 0.0f) {
                if (state.playerIsGhost || state.bandages < 1) state.bandageT = -1.0f;
                else if ((state.bandageT -= dt) <= 0.0f) { state.bandageT = -1.0f; state.logLine = ApplyBandage(state); PlaySfx(SfxId::Heal); }
            }
        }
        WarNetTick(state, dt); // War Week: Muster minutes, online guild sync (2026-09-27)
        g_tapWalkOn = state.optTapWalk;
        g_alwaysDay = state.optAlwaysDay;
        g_sfxOn = state.optSfx; g_musicOn = state.optMusic;
        g_calmMusic = state.optCalmMusic; g_musicVol = state.optMusicVol; g_sfxVol = state.optSfxVol;
        state.town3DView = state.wild3DView = state.interior3DView = state.hunt3DView = true; // 3D only (the classic 2D view was retired 2026-09-28)
        { // stat buffs run out; HP and mana follow the effective stats (2026-09-27)
            for (float* t : { &state.blessT, &state.strPotT, &state.agiPotT }) if (*t > 0.0f && (*t -= dt) <= 0.0f) {
                *t = 0.0f;
                Journal(state, t == &state.blessT ? "The Bless fades." : (t == &state.strPotT ? "Your Strength potion wears off." : "Your Agility potion wears off."));
            }
            int mh = EffStr(state);
            if (state.maxHp != mh) { state.maxHp = mh; if (state.hp > mh) state.hp = mh; }
            if (state.mana > MaxMana(state)) state.mana = MaxMana(state);
        }
        UpdateCombatAnim(state, dt);
        UpdateDeathAndRespawn(state, dt); // death anims, ghost timer, monster respawns, corpse fades
        UpdateGuildOffscreen(state, dt);  // the rival and Murder Inc. keep living while you're elsewhere

        if (state.youngT > 0.0f && (state.screen == Screen::Wilderness || state.screen == Screen::Town || state.screen == Screen::Hunt)) {
            state.youngT -= dt; // Young time only runs while you're out playing
            if (state.youngT <= 0.0f) {
                state.youngT = 0.0f;
                if (state.starterStep < 0) {
                    state.logLine = "You are no longer Young - Murder Inc. may hunt you now. Train Tracking to hear them coming.";
                    Journal(state, state.logLine);
                }
            }
        }
        { // Tracking (2026-09-27): reading the land while you roam the wilderness - slow and steady
            static float trackT = 0.0f;
            if (state.screen == Screen::Wilderness && !state.playerIsGhost && (trackT += dt) >= 12.0f) {
                trackT = 0.0f;
                SkillUseGain(state.tracking, 0.5f, 1.5f);
            }
        }
        // JS: autosave every 2 seconds (setInterval(() => { render(); save(); }, 2000)).
        autosaveTimer += dt;
        if (autosaveTimer >= 2.0f) {
            autosaveTimer = 0.0f;
            SaveGame(state);
        }
        if (resetArmedTimer > 0.0f) {
            resetArmedTimer -= dt;
            if (resetArmedTimer <= 0.0f) state.logLine = "Reset cancelled.";
        }

        // JS: after a gather completes, roll for an ambush/innocent encounter, then
        // (if nothing triggered) let auto-gather chain into its next action.
        if (!state.pendingEncounterCheck.empty()) {
            std::string src = state.pendingEncounterCheck;
            state.pendingEncounterCheck.clear();
            bool triggered = TryTriggerAmbush(state, src);
            if (!triggered) triggered = TryTriggerInnocentEncounter(state, src);
            if (triggered) {
                state.autoGather = false;
            } else if (state.autoGather && src == "gather") {
                std::string next = NextAutoGatherType(state);
                if (next.empty()) {
                    state.autoGather = false;
                    state.logLine = "Auto-gather complete - Mining and Lumberjacking both reached 100.";
                } else {
                    TryStartGather(state, next);
                }
            }
        }

        bool encounterPending = state.ambush.has_value() || state.innocentEncounter.has_value();

        // --- Input: keyboard shortcuts for gathering (1/2/3) and closing the building
        // panel (ESC); movement (WASD/arrows) and interaction (E) are handled inside
        // DrawTownScreen itself, since they need the frame's nearest-node lookup. ---
        if (!encounterPending && state.screen == Screen::Town) {
            if (IsKeyPressed(KEY_ESCAPE)) state.selectedTile.reset();
        }
        if (!encounterPending && state.screen == Screen::Wilderness) {
            if (IsKeyPressed(KEY_M)) { // minimap toggle
                state.worldMapOpen = false;
                state.minimapOpen = !state.minimapOpen;
                if (state.minimapOpen) state.journalOpen = false; // 2026-09-25 art-pass fix: avoid the panel overlap
            }
        }
        if (!encounterPending && state.screen == Screen::Interior) {
            // Interiors stay part of the town: ESC closes a popup or steps back outside through the door.
            if (IsKeyPressed(KEY_ESCAPE)) {
                if (state.selectedTile.has_value() || state.interiorGreeted) {
                    state.selectedTile.reset();
                    state.interiorGreeted = false;
                } else ExitInterior(state);
            }
        }
        if (!encounterPending && state.screen == Screen::Hunt && !state.combat.has_value()) {
        }
        // --- Input: combat shortcuts, only meaningful on Hunt while fighting ---
        if (!encounterPending && state.screen == Screen::Hunt && state.combat.has_value()) {
            if (IsKeyPressed(KEY_A)) ResolveCombatRound(state);
            if (IsKeyPressed(KEY_F)) FleeCombat(state);
            if (IsKeyPressed(KEY_B)) UseBandageInCombat(state);
        }
        // --- Input: switch screens with Tab (cycles Character -> Town -> Hunt -> Craft -> Magic -> Pets -> Bank -> House -> Skills -> Guide -> Character) ---
        if (!encounterPending && !DenFighting() && IsKeyPressed(KEY_TAB)) {
            if (!(state.screen == Screen::Hunt && state.combat.has_value())) { // don't tab away mid-fight
                Screen next = IsPlayScreen(state.screen) ? Screen::Character // (2026-09-27) the world, then the menus, then back
                            : (state.screen == Screen::Character) ? Screen::Craft
                            : (state.screen == Screen::Craft) ? Screen::Magic
                            : (state.screen == Screen::Magic) ? Screen::Pets
                            : (state.screen == Screen::Pets) ? Screen::Bank
                            : (state.screen == Screen::Bank) ? Screen::House
                            : (state.screen == Screen::House) ? Screen::Skills
                            : (state.screen == Screen::Skills) ? Screen::Guide : g_playScreen;
                GuardZoneConfiscateIfMurderer(state, next); // JS switchTab(): Murderer tier gets bounced from Craft
                state.screen = next;
                if (next == Screen::Guide) state.guidePage = 0;
            }
        }

        // --- 3D town sun-shadow pass: renders depth from the light's POV into the
        // shadowmap (see Town3DShadowPass), capturing the light VP matrix the
        // main 3D pass needs. Must run while the default framebuffer is bound,
        // before BeginTextureMode(g_zoomTarget)/BeginDrawing below. 2D screens
        // are untouched (guarded by town3DView).
        if (state.screen != Screen::Character) g_pdTryOn.reset();
        if (state.screen == Screen::Character) PaperdollRenderPass(state); // the 3D body for the paperdoll
        else if (state.screen == Screen::Town && state.town3DView) Town3DShadowPass(state);
        else if (state.screen == Screen::Wilderness && state.wild3DView) {
            // Frustum cull for the shadow pass (Phase 1 deferred item): reuse the
            // damped main camera - calling Wild3DGetCam twice a frame just eases
            // the damping a touch faster, visually negligible.
            Town3DCam wildCull = Wild3DGetCam(state, screenW, screenH);
            Wild3DShadowPass(state, &wildCull);
        }

        // --- Draw ---
        bool wideWorld=!IsMenuScreen(state.screen) && (ExploreHeaderCollapsed(state) || (state.screen==Screen::Hunt && state.selectedDungeon.has_value() && state.hunt3DView)) && !state.ambush.has_value() && !state.innocentEncounter.has_value();
        const Screen frameScreen=state.screen;
        LandscapeBeginFrame(wideWorld,LandscapeDialogOpen(state),(int)state.screen,state.screen==Screen::Character && !g_characterPack);
        ClearBackground(wideWorld ? BLANK:kColorPageBg);

        // Inside a dungeon (2026-09-25), and in the 3D town/wilderness/interior
        // views (2026-09-26): the header - title, Reset, resource HUD, tab bar -
        // collapses behind a MENU toggle (DrawCompactMenu) so the world gets
        // nearly the full screen. The 3D views draw over this strip anyway, so
        // skipping it also stops invisible tabs/Reset from taking taps.
        bool inDungeon = (state.screen == Screen::Hunt && state.selectedDungeon.has_value());
        bool explore3D = ExploreHeaderCollapsed(state) && !state.ambush.has_value() &&
                         !state.innocentEncounter.has_value();
        if (!explore3D) state.exploreMenuOpen = false;
        // Shield the MENU button (and the open dropdown) from the screen's own
        // buttons, which are drawn before it.
        if (state.screen != Screen::Wilderness) state.worldMapOpen = false;
        g_uiShieldOn = explore3D;
        g_uiShield = state.exploreMenuOpen ? CompactMenuPanelRect(false) : kCompactMenuBtn;
        if (state.worldMapOpen || state.guideOpen) { g_uiShieldOn = true; g_uiShield = { 0, 0, (float)screenW, (float)screenH }; }
        if (state.exploreMenuOpen && !state.worldMapOpen && !state.guideOpen) {
            g_uiShield.y = kCompactMenuBtn.y; // cover the toggle too
            g_uiShield.height += CompactMenuPanelRect(false).y - kCompactMenuBtn.y;
        }
        if (!explore3D) {
        DrawUIText("TOWN FORGE", 20, 16, 22, kColorHeading);
        DrawUIText("Your power comes from what you build", 20, 40, 13, DARKGRAY);

        // Reset (top-right corner): first click arms it, a second click within 3s
        // confirms - a small safety net the JS's single-click reset link didn't have.
        bool resetArmed = resetArmedTimer > 0.0f;
        std::string resetLabel = resetArmed ? "Confirm?" : "Reset";
        if (Button({ (float)(screenW - 78), 16, 58, 22 }, resetLabel, !encounterPending && !state.combat.has_value())) {
            if (resetArmed) {
                ResetGame(state); resetArmedTimer = 0.0f;
#ifdef __EMSCRIPTEN__
                JS_CloudOnReset(); // cloud keeps the old character until you choose
#endif
            }
            else resetArmedTimer = 3.0f;
        }
#ifdef __EMSCRIPTEN__
        { // Cloud saves (2026-09-27): button + status dot, left of Reset (only when configured)
            int cs = JS_CloudState();
            if (cs > 0) {
                Rectangle cb = { (float)(screenW - 150), 16, 64, 22 };
                if (Button(cb, "Cloud", true)) JS_CloudOpen();
                Color dot = cs == 2 ? Color{ 90, 200, 110, 255 } : cs == 3 ? Color{ 120, 170, 255, 255 }
                          : cs == 4 ? Color{ 240, 170, 60, 255 } : Color{ 150, 150, 150, 255 };
                DrawCircle((int)(cb.x + cb.width - 7), (int)cb.y + 6, 4.0f, dot);
            }
        }
#endif
        }

        if (!inDungeon && !explore3D) {
        // Resource HUD (mirrors .resources pill row in the HTML) - shown on all screens
        std::string hud = TextFormat("Gold: %d   Wood: %d   Ore: %d   Leather: %d   Fish: %d   Furs: %d   Ice: %d",
                                       state.gold, state.wood, state.ore, state.leather, state.fish, state.furs, state.ice);
        DrawUIText(hud.c_str(), 20, 60, 15, kColorText);

        // Top tab bar (mirrors the JS bottom-nav tabs), on its own row now that
        // there are 9 of them.
        bool tabsEnabled = !state.combat.has_value() && !encounterPending &&
                             !state.playerIsGhost && state.playerDeathAnimT <= 0.0f; // ghosts can't tab-travel
        // Hunt tab hidden 2026-09-23 at Mark's request - now that every dungeon has a
        // real Wilderness entrance you can walk to (see kWildernessDungeonEntrances),
        // the tab was just a redundant "teleport straight to a dungeon picker"
        // shortcut, and looting/skinning already work identically in live Wilderness
        // combat (EndWildMonsterWin already pushes a corpse with real leather, same as
        // dungeons). The Hunt *screen* itself is untouched and still fully reachable by
        // walking into a Wilderness dungeon entrance (tryEnterDungeon still sets
        // Screen::Hunt) - only this tab-bar shortcut is gone. Single switch, not a
        // deletion, same pattern as kAmbushSystemEnabled/kBloodstainedRoadEnabled.
        // Remaining tabs shift left to fill the gap (via `tabX` not advancing past
        // Hunt's slot) rather than leaving an empty space in the bar.
        static const bool kHuntTabEnabled = false;
        float tabX = 20.0f;
        Rectangle charTab   = { tabX, 84, 53, 26 }; tabX += 56;
        Rectangle townTab   = { tabX, 84, 84, 26 }; tabX += 87; // widened for town names
        Rectangle craftTab  = { tabX, 84, 53, 26 }; tabX += 56;
        Rectangle huntTab   = { tabX, 84, 53, 26 }; if (kHuntTabEnabled) tabX += 56;
        Rectangle magicTab  = { tabX, 84, 53, 26 }; tabX += 56;
        Rectangle petsTab   = { tabX, 84, 53, 26 }; tabX += 56;
        Rectangle bankTab   = { tabX, 84, 53, 26 }; tabX += 56;
        Rectangle houseTab  = { tabX, 84, 53, 26 }; tabX += 56;
        Rectangle skillsTab = { tabX, 84, 53, 26 };
        Rectangle guideTab  = { tabX + 56, 84, 40, 26 }; // newbie walkthrough (2026-09-25)
        if (Button(charTab, "Me", tabsEnabled)) state.screen = Screen::Character;
        // (2026-09-27) the way back into the game, made obvious: a glowing gold "Play"
        DrawRectangleRounded({ townTab.x - 3, townTab.y - 3, townTab.width + 6, townTab.height + 6 }, 0.35f, 6,
                             Fade(Color{ 255, 196, 70, 255 }, 0.55f + 0.25f * sinf((float)GetTime() * 3.0f)));
        if (Button(townTab, "> Play", tabsEnabled)) state.screen = g_playScreen; // back where you were, not a teleport to town
        if (Button(craftTab, "Craft", tabsEnabled)) {
            Screen target = Screen::Craft;
            GuardZoneConfiscateIfMurderer(state, target);
            state.screen = target;
        }
        if (kHuntTabEnabled && Button(huntTab, "Hunt", tabsEnabled)) state.screen = Screen::Hunt;
        if (Button(magicTab, "Magic", tabsEnabled)) state.screen = Screen::Magic;
        if (Button(petsTab, "Pets", tabsEnabled)) state.screen = Screen::Pets;
        if (Button(bankTab, "Bank", tabsEnabled)) state.screen = Screen::Bank;
        if (Button(houseTab, "House", tabsEnabled)) state.screen = Screen::House;
        if (Button(skillsTab, "Skills", tabsEnabled)) state.screen = Screen::Skills;
        if (Button(guideTab, "Help", tabsEnabled)) { state.screen = Screen::Guide; state.guidePage = 0; }
        } // end if (!inDungeon): HUD + tab bar hidden inside dungeons

        Screen renderedScreen = state.screen;
        if (state.ambush.has_value()) {
            DrawAmbushPanel(state, screenW);
        } else if (state.innocentEncounter.has_value()) {
            DrawInnocentPanel(state, screenW);
        } else if (state.screen == Screen::Character) {
            DrawCharacterScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Blackwake) {
            DrawBlackwakeScreen(state,screenW,screenH);
        } else if (state.screen == Screen::Town) {
            DrawTownScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Interior) {
            DrawInteriorScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Hunt) {
            DrawHuntScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Craft) {
            DrawCraftScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Magic) {
            DrawMagicScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Pets) {
            DrawPetsScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Bank) {
            DrawBankScreen(state, screenW, screenH);
        } else if (state.screen == Screen::House) {
            DrawHouseScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Skills) {
            DrawSkillsScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Guide) {
            DrawGuideScreen(state, screenW); // newbie walkthrough, reopenable anytime
        } else if (state.screen == Screen::Provisioner) {
            // No tab-bar button and not in the Tab-key cycle below - same treatment as
            // Wilderness, reached only by walking to the building (see DrawTownScreen's
            // AmenityLink for Provisioner). The tab bar's 9 buttons already fill the row.
            DrawProvisionerScreen(state, screenW, screenH);
        } else if (state.screen == Screen::FurTrader) {
            // Phase 3 - same treatment as Provisioner: reached only by walking to the
            // Fur Trader in Frostmere.
            DrawFurTraderScreen(state, screenW, screenH);
        } else if (state.screen == Screen::MinersGuild) {
            // Phase 4 - same treatment as Provisioner/FurTrader: reached only by
            // walking to the Miners' Guild in Cragmoor.
            DrawMinersGuildScreen(state, screenW, screenH);
        } else if (state.screen == Screen::Refuge) {
            // Phase 6 - reached only by walking to the outlaw refuge as a red.
            DrawRefugeScreen(state, screenW, screenH);
        } else {
            DrawWildernessScreen(state, screenW, screenH);
        }
        // 3D exploration MENU (2026-09-26), drawn over the world like the
        // dungeon's. Skipped on the frame a screen switch happened.
        // Arrival titles provide the transition cue; never cover the gameplay
        // with a black portrait-sized fade or add a fixed wait to entering an area.
        g_screenFadeT=0.0f;
        if (g_zoneTitleT > 0.0f) { // the place's name as you arrive
            float t = kZoneTitleTime - g_zoneTitleT;
            float a = std::min(std::clamp((t - 0.2f) / 0.4f, 0.0f, 1.0f), std::clamp(g_zoneTitleT / 0.6f, 0.0f, 1.0f));
            int fs = 30;
            int tw = MeasureUIText(g_zoneTitle.c_str(), fs);
            int ty = screenH / 3;
            DrawRectangleGradientH(screenW / 2 - tw / 2 - 90, ty - 10, tw / 2 + 90, fs + 20, Fade(BLACK, 0.0f), Fade(BLACK, 0.55f * a));
            DrawRectangleGradientH(screenW / 2, ty - 10, tw / 2 + 90, fs + 20, Fade(BLACK, 0.55f * a), Fade(BLACK, 0.0f));
            DrawUIText(g_zoneTitle.c_str(), screenW / 2 - tw / 2 + 2, ty + 2, fs, Fade(BLACK, 0.6f * a));
            DrawUIText(g_zoneTitle.c_str(), screenW / 2 - tw / 2, ty, fs, Fade(Color{ 244, 222, 160, 255 }, a));
            g_zoneTitleT = fmaxf(0.0f, g_zoneTitleT - GetFrameTime());
        }
        if (state.screen == Screen::Wilderness && state.worldMapOpen) {
            DrawWorldMap(state); // full map (tap the minimap): above everything, any tap closes
        } else if (explore3D && ExploreHeaderCollapsed(state)) {
            DrawCompactMenu(state, state.exploreMenuOpen, false);
        }
        g_uiShieldOn = false;

        // Newbie guide (2026-09-25): on a fresh save's first visit to town or
        // the wilderness - and only then - open the walkthrough overlay. Never
        // inside dungeons, never mid-fight; a fresh save that somehow opens
        // mid-dungeon simply defers until town/wilderness.
        bool guideHome = (state.screen == Screen::Town || state.screen == Screen::Wilderness);
        bool guideBlocked = state.wildEngaged.has_value() || state.dungeonEngaged.has_value() ||
                            state.combat.has_value() || state.ambush.has_value() ||
                            state.playerIsGhost || state.playerDeathAnimT > 0.0f;
        // (2026-09-27) new players now get the "first steps" goals instead of the
        // five-page overlay; the pages live on under Help.
        (void)guideBlocked;
        if (state.guideOpen && guideHome) { g_uiShieldBypass = true; DrawGuideOverlay(state); g_uiShieldBypass = false; }
        if (!guideBlocked || state.starterStep == kStFight || state.starterStep == kStLoot) UpdateDrawStarter(state, screenW, screenH);
        DrawDirectionsHud(state, screenW); // compass + world-boss timer (2026-09-27)
        DrawWalkMarker(state);             // tap to walk + Teleport aim (2026-09-27)
        if (state.hidden && state.screen != Screen::Wilderness && state.screen != Screen::Hunt) state.hidden = false; // (2026-09-28)
        if (state.hidden && !state.exploreMenuOpen && state.openCorpseId < 0) DrawHudLine(EffectiveSkill(state, &GameState::stealth) > 0.0f ? "HIDDEN - sneaking (Stealth)" : "HIDDEN - moving will reveal you", 20, 244, 13, Color{ 200, 190, 255, 255 });
        g_hudCamZone = -1;
        // UO-style travel (2026-09-25): arriving in a town marks it as a recall
        // destination. selectedTown only changes on real arrivals (gates, tabs,
        // resurrect, recall), so this one hook catches every path - no per-gate
        // calls needed.
        if ((state.screen == Screen::Town) && state.selectedTown != state.lastTownMarkedIdx) {
            MarkTownVisited(state, state.selectedTown);
            state.lastTownMarkedIdx = state.selectedTown;
        }

        // Messages (2026-09-27): every new log line pops up as a toast - on the world
        // screens above the belt and spell bar, on menus at the bottom - colored by
        // what it means. The old faint line at the very bottom hid under the spell bar.
        MpTick(state);           // (2026-09-29) multiplayer: send where you are, hear everyone else
        if (state.screen == renderedScreen) MpDrawChatButton(state); // never reuse a navigation tap on newly shown Chat
        UpdateDrawToasts(state, screenW, screenH, IsPlayScreen(state.screen));
        UpdateDrawLevelUps(state, screenW, screenH, IsPlayScreen(state.screen)); // (2026-09-29) RuneScape-style level-ups
        DrawNotorietyFooter(state, screenW, screenH);

        // A button may have opened or closed a panel during this frame. Present
        // the final state, rather than guessing from the size of HUD controls.
        if(state.screen!=frameScreen) {
            // Draw functions can navigate before rendering their world. Keep the
            // last complete screen and still finish the frame to advance input.
            LandscapeHoldFrame();EndDrawing();return;
        }
        g_landscapeDialog=LandscapeDialogOpen(state);
        LandscapePresent(UiFont(),g_uiRects);
        EndDrawing();
        WarmWildernessCache(state);
    }
}


int main() {
#ifdef TF_TOWNSCAN
    TownCompoundScan();
#endif
    g_skillOwner = &g_state; // the skill loadout cap (2026-09-27)
    std::srand((unsigned)std::time(nullptr));
    InitWindow((int)tflayout::width,(int)tflayout::height,"Town Forge");
    g_landscapeUI=LoadRenderTexture(kScreenW,kScreenH);
    g_landscapeScene=LandscapeLoadScene(kScreenW,kScreenH);
    SetTextureFilter(g_landscapeUI.texture,TEXTURE_FILTER_BILINEAR);
    SetTextureFilter(g_landscapeScene.texture,TEXTURE_FILTER_BILINEAR);
    g_zoomTarget=g_landscapeUI;
    SetTargetFPS(60);
    // 2026-09-24: raylib's desktop build (RL_CULL_DISTANCE_FAR=4000) and the
    // web/em++ build (raylib-src default 1000) disagreed on the far clip
    // plane, so the 3D Wilderness sky/scatter got silently far-clipped on web
    // only - a bug the desktop sandbox structurally cannot reproduce.
    // Setting an explicit, platform-independent far plane here - comfortably
    // past every 3D view's farthest zoom/sky radius - removes the discrepancy
    // for good.
    // 2026-09-25: near plane 0.05 -> 10. Every 3D camera sits at least 150 units
    // from its target, so nothing is ever that close, and a 0.05 near plane
    // threw away almost all depth precision (far/near = 100000): at 1500 units
    // a 24-bit depth step was ~2.7 world units, the root cause of the earlier
    // long-distance z-fighting. At 10 it's ~0.01, which is what lets the
    // contact shadows sit 1 unit above the ground without flickering.
    rlSetClipPlanes(10.0, 5000.0);
    InitSfx(); // audio device + synthesized SFX bank (missing files stay silent)
    LoadGameAssets(); // must come after InitWindow - texture loading needs a graphics context

#ifdef __EMSCRIPTEN__
    // Kick off the async IndexedDB mount+load now; LoadGame itself is deferred to
    // inside UpdateDrawFrame until JS_PersistReady() confirms the load landed, rather
    // than called here synchronously - see the comments above kSaveFilePath and at the
    // top of UpdateDrawFrame.
    JS_InitPersistence();
    // The browser's requestAnimationFrame drives each call; no blocking loop, no
    // WindowShouldClose() polling, no ASYNCIFY needed - see UpdateDrawFrame's comment.
    emscripten_set_main_loop(UpdateDrawFrame, 0, 1);
#else
    bool hadSave = LoadGame(g_state); // applies offline Auto-Gather catch-up internally
    if (hadSave && !g_state.logLine.empty() && g_state.logLine == "Welcome to Town Forge.")
        g_state.logLine = "Welcome back.";
    if (hadSave) SettleCatchUp(g_state);
    while (!WindowShouldClose()) UpdateDrawFrame();
    CleanupAndClose();
#endif
    return 0;
}
